WITH payload AS (SELECT $archive_payload$[{"id":"bcf2ef59-3f85-5aed-8215-8fc319b44b3d","document_type":"judgment","category":"judicial","subcategory":"general","title":"إخال باألمن الوطني -جرائم معلوماتية -تخزين ما من شأنه املساس بالنظام العام -العبرة باإلقرار احلاصل أمام القضاء - متابعة مواقع الكترونية تسعى لهدم نظام احلكم -تقرير فني - إخاء سبيل -بينة غير موصلة -رد دعوى -حفظ حق املدعى عليه يف التعويض -عجز املدعي العام عن إثبات دعواه.","document_number":"4/34/37","case_number":"768","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/25","year":"1434","subject":"إخال باألمن الوطني -جرائم معلوماتية -تخزين ما من شأنه املساس بالنظام العام -العبرة باإلقرار احلاصل أمام القضاء - متابعة مواقع الكترونية تسعى لهدم نظام احلكم -تقرير فني - إخاء سبيل -بينة غير موصلة -رد دعوى -حفظ حق املدعى عليه يف التعويض -عجز املدعي العام عن إثبات دعواه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 4/34/37 :‬وتاريخ ‪1434/11/25:‬هـ‬\n                              ‫رقم الدعوى‪768 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪/1/449‬ص وتاريخ ‪1435/2/7:‬هـ‬\n\n\n      ‫إخــال باألمــن الوطنــي‪ -‬جرائــم معلوماتيــة ‪ -‬تخزيــن مــا مــن شــأنه‬\n      ‫املســاس بالنظــام العــام‪ -‬العبــرة باإلقــرار احلاصــل أمــام القضــاء ‪-‬‬\n      ‫متابعــة مواقــع الكترونيــة تســعى لهــدم نظــام احلكــم ‪ -‬تقريــر فنــي ‪-‬‬\n      ‫إخــاء ســبيل ‪ -‬بينــة غيــر موصلــة‪ -‬رد دعــوى ‪ -‬حفــظ حــق املدعــى‬\n                ‫عليــه يف التعويــض ‪ -‬عجــز املدعــي العــام عــن إثبــات دعــواه‪.‬‬\n\n\n\n\n                                                  ‫‪ -1‬األصل براءة الذمة‪.‬‬\n                    ‫‪ -2‬الدليل إذا تطرق إليه االحتمال سقط به االستدالل‪.‬‬\n                                      ‫‪ -3‬االعتراف ال يتجزأ على صاحبه‪.‬‬\n                       ‫‪ -4‬املادتان (‪ )195-194‬من نظام االجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫أقــام املدعــي العــام دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن‬\n      ‫طلــب إدانتــه بتخزيــن مــا مــن شــأنه املســاس بالنظــام العــام عــن طريــق‬\n      ‫الشــبكة املعلوماتيــة (اإلنترنــت)‪ ،‬ومتابعــة مواقــع الكترونيــة تســعى‬\n      ‫لهــدم نظــام احلكــم‪ ،‬وطلــب احلكــم عليــه بالعقوبــة املنصــوص عليهــا‬\n      ‫باملــادة (‪ )6‬مــن نظــام مكافحــة اجلرائــم املعلوماتيــة‪ ،‬ومبصــادرة جهــازي‬\n      ‫احلاســب اآللــي املضبوطــن لــدى املدعــى عليــه وبعقوبــة تعزيريــة ومبنعــه‬\n\n‫‪227‬‬\n\f‫مــن الســفر‪ ،‬حيــث قبــض علــى املدعــى عليــه إثــر توافــر معلومــات‬\n‫مفادهــا قيامــه بدعــم اجلماعــات املســلحة يف دولــة مجــاورة وبتفتيــش‬\n‫ـط لديــه جهــازا حاســب آلــي محمــول وبفحصهمــا تبــن‬           ‫منزلــه ُض ِبـ َ‬\n‫احتواؤهمــا علــى مقاطــع فيديــو متــس النظــام العــام وكذلــك زيــارات‬\n‫ملواقــع الكترونيــة معاديــة ‪،‬ومبواجهتــه بالدعــوى أمــام احملكمــة‬\n‫أنكــر مــا جــاء يف الدعــوى جملــة وتفصيــا ‪،‬ولــم يقــدم املدعــي العــام‬\n‫ا مســتقيم ًا علــى أن املدعــى عليــه هــو الــذي قــام بتخزيــن املــواد‬  ‫دلي ـ ً‬\n‫املشــار إليهــا يف تقريــر فحــص املضبوطــات أو قــام بالدخــول علــى مواقــع‬\n‫محجوبــة‪ ،‬وملــا كان مقــررا أن الدليــل إذا تطــرق إليــه االحتمــال ســقط‬\n‫بــه االســتدالل‪ ،‬وأن األصــل بــراءة الذمــة لذلــك قضــت احملكمــة بعــدم‬\n‫ثبــوت إدانــة املدعــى عليــه مبــا أســند إليــه يف الدعــوى وأخلــت ســبيله‬\n‫منهــا لعــدم كفايــة الدليــل وقنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n ‫املدعــي العــام وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬فلــدي أنــا القاضــي باحملكمــة اجلزائيــة‬\n‫املتخصصــة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة املتخصصــة املكلــف برقــم ‪ 768‬وتاريــخ ‪1433/10/28‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33/10953‬وتاريــخ ‪1433/10/28‬ه ـ ويف يــوم‬\n‫االثنــن ‪1434/1/26‬ه ـ الســاعة الواحــدة والربــع افتتحــت اجللســة وفيهــا‬\n‫حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه رغــم طلــب حضــوره‬\n‫مبوجــب خطابنــا رقــم ‪ 34/350‬وتاريــخ ‪1434/1/6‬ه ـ وقــدم املدعــي‬\n‫العــام الئحــة الدعــوى ونصهــا مــا يل ــي ‪( :‬بصفتــي مدعي ـ ًا عام ـ ًا بهيئــة‬\n\n                                                                                      ‫‪228‬‬\n\f      ‫التحقيــق واالدعــاء العــام أدعــي علــى ‪ ، /‬تاريــخ امليــاد ‪1385 :‬ه ـ ‪،‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ، )......‬املؤهــل شــهادة‬\n      ‫الثانويــة ‪ ،‬املوقــوف ســابقا وأطلــق ســراحه بتاريــخ ‪1432/9/26‬ه ـ ‪.‬‬\n      ‫بارتــكاب اجلرائــم التاليــة ‪ -:‬تخزينــه عــن طريــق الشــبكة املعلوماتيــة‬\n      ‫(اإلنترنــت) مــا مــن شــأنه املســاس بالنظــام العــام وذلــك مــن خــال قيامــه‬\n      ‫بتخزيــن مقاطــع فيديــو للهالكــن‪............./‬و‪ ........‬يحثــان فيهــا علــى‬\n      ‫القتــال املجــرم مبوجــب املــادة السادســة الفقــرة (‪ )1‬مــن نظــام جرائــم‬\n      ‫املعلوماتيــة الصــادر باملرســوم امللكــي رقــم م‪ 17/‬وتاريــخ ‪1428/3/8‬ه ـ‬\n      ‫‪ .‬متابعــة مــا يســمى ‪ ....‬التابــع للمــارق‪ - ..../‬الــذي أعلــن احلــرب والعــداء‬\n      ‫ويســعى لهــدم نظــام احلكــم وتدميــر مقومــات املجتمــع والنيــل مــن أمنــه‬\n      ‫واســتقراره ‪ -‬ممــا يشــير إلــى تأثــره بأفــكاره املنحرفــة ‪ .‬حيــث مت‬\n      ‫القبــض علــى املذكــور بالتاريــخ املنــوه عنــه أعــاه إثــر توافــر معلومــات‬\n      ‫مفادهــا قيامــه بدعــم اجلماعــات املســلحة يف دولــة ‪ ............‬وبتفتيــش‬\n      ‫منزلــه ضبــط لديــه جهــازي حاســب آلــي محمــول وبفحصهمــا تبــن‬\n      ‫احتواؤهمــا علــى مقاطــع فيديــو للهالكــن‪................/‬و‪ ............‬يحثــان‬\n      ‫فيهــا علــى القتــال ومقاطــع فيديــو لعمليــات عســكرية يف ‪ ....‬وكذلــك‬\n      ‫زيــارات ل ـ ‪ ....‬التابــع للمــارق‪ . ......../‬وباســتجوابه أقــر حتقيق ـ ًا بأنــه‬\n      ‫تعــرف علــى موقــع ‪ ....‬علــى الشــبكة املعلوماتيــة (اإلنترنــت) بإجــازة‬\n      ‫عيــد الفطــر ‪1430‬ه ـ وقــد فتحــه وشــاهد فيــه مناظــرات ومنهــا مقاطــع‬\n      ‫فيديــو لعمليــات عســكرية ‪ .............‬ومقاطــع ‪ .......‬و‪.........‬علمـ ًا بأنــه ال‬\n      ‫يذكرهــا موضحـ ًا أنــه كان يشــاهد مقاطــع فقــط إمــا بنهايــة األســبوع‬\n      ‫أو باإلجــازات ولــم يكــن يشــاهدها كاملــة لطــول مدتهــا كمــا كان‬\n      ‫يــزور بعــض املواقــع مثــل ‪ ....‬وجميعهــا كان يشــاهدها حلــب االســتطالع‬\n\n\n‫‪229‬‬\n\f‫‪ -‬حســب تعبيــره ‪ -‬فقــط‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام لــه‬\n‫مبــا أســند إليــه لألدلــة والقرائــن التاليــة ‪ -:‬مــا جــاء بأقوالــه حتقيق ـ ًا‬\n‫املــدون علــى دفتــر التحقيــق املرفــق ‪ .‬مــا جــاء بنتائــج فحــص أجهــزة‬\n‫احلاســب اآللــي املضبوطــة لديــه ‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫هــو فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا وموجــب مــن موجبــات‬\n‫التعازيــر لــذا أطلــب مــا يلــي ‪ -:‬إدانتــه مبــا أســند إليــه شــرع ًا ‪ .‬تطبيــق‬\n‫العقوبــة املنصــوص عليهــا باملــادة السادســة مــن نظــام مكافحــة اجلرائــم‬\n‫املعلوماتيــة املشــار إليــه بحدهــا األعلــى‪ .‬احلكــم مبصــادرة جهــازي‬\n‫احلاســب اآللــي املضبوطــن لــدى املدعــى عليــه وفق ـ ًا للمــادة (‪ )13‬مــن‬\n‫النظــام ذاتــه‪ .‬احلكــم عليــه بعقوبــة تعزيريــة شــديدة تزجــره وتــردع غيــره‬\n‫‪ .‬احلكــم مبنعــه مــن الســفر اســتناد ًا للمــادة السادســة الفقــرة الثانيــة‬\n‫مــن نظــام وثائــق الســفر) انتهــى هكــذا ادعــى ورفعــت اجللســة لطلــب‬\n‫حضــور املدعــى عليــه لتــاوة الدعــوى عليــه يف اجللســة احملــددة يف يــوم‬\n‫االثنــن ‪1434/4/22‬ه ـ ‪ .‬وأقفلــت الســاعة الواحــدة والنصــف وصلــى‬\n‫اهلل علــى نبينــا محمــد وحــرر يف ‪1434/1/26‬ه ـ ‪ .‬احلمــد هلل وحــده‬\n‫وبعــد ويف يــوم االثنــن ‪1434/4/22‬ه ـ فتحــت اجللســة الســاعة الواحــدة‬\n‫وخمــس وثالثــن دقيقــة وفيهــا حضــر املدعــي العــام ‪ ........‬ولــم يحضــر‬\n‫املدعــى عليــه‪ ............../‬رغــم طلــب حضــوره بخطابنــا رقــم ( ‪34/7266‬‬\n‫) وتاريــخ ‪1434/4/10‬ه ـ وأقفلــت اجللســة الســاعة الواحــدة وخمــس‬\n‫وأربعــن دقيقــة وتأجلــت اجللســة إلــى يــوم الثالثــاء ‪1434/6/6‬ه ـ وصلــى‬\n                         ‫اهلل علــى نبينــا محمــد وحــرر يف ‪1434/4/22‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1434/6/6‬ه ـ فتحــت اجللســة‬\n‫الســاعة العاشــرة والربــع وفيهــا حضــر املدعــي العــام‪ .... /‬وحضــر حلضور‬\n\n\n                                                                                        ‫‪230‬‬\n\f      ‫املدعــى عليــه‪ .............. /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‬\n      ‫‪ ) ..........‬وبتــاوة الدعــوى عليــه‪ ،‬وإفهامــه بحقــه يف اســتالم نســخة مــن‬\n      ‫الئحــة الدعــوى‪ ،‬وتوكيــل محــام أو وكيــل شــرعي للترافــع عنــه يف‬\n      ‫هــذه القضيــة قــرر قائ ـاً‪ :‬أطلــب تســليمي نســخة مــن الئحــة الدعــوى‬\n      ‫لإلجابــة عنهــا يف اجللســة القادمــة هكــذا قــرر‪ ،‬وأضــاف قائـاً‪ :‬وكلت‬\n      ‫احملامــي‪ .........../‬باملدافعــة واملرافعــة عنــي يف هــذه القضيــة ولــه حــق‬\n      ‫تقــدمي املذكــرات اجلوابيــة واللوائــح االعتراضيــة هكــذا قــرر فجــرى‬\n      ‫إثبــات الوكالــة بالصفــة الــواردة أعــاه‪ ،‬ورفعــت اجللســة لتمكــن‬\n      ‫املدعــى عليــه مــن تقــدمي جوابــه يف اجللســة القادمــة‪ ،‬وتأجلــت إلــى يــوم‬\n      ‫الســبت ‪1434/7/29‬هـ وأقفلت اجللســة الســاعة العاشــرة وأربعني دقيقة‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وحــرر يف ‪1434/6/6‬ه ـ ‪ .‬احلمــد هلل وحــده‬\n      ‫و يف يــوم الســبت ‪1434/7/29‬ه ـ الســاعة الواحــدة وفيهــا حضــر املدعي‬\n      ‫العــام‪ .............. /‬ولــم يحضــر املدعــى عليــه ‪ ................... /‬رغــم طلــب‬\n      ‫حضــوره مبوجــب خطابنــا رقــم ‪ 34/14113‬وتاريــخ ‪1434/7/15‬ه ـ لــذا‬\n      ‫رفعــت اجللســة لطلــب حضــوره وتأجلــت إلــى يــوم األحــد ‪1434/8/16‬ه ـ‬\n      ‫وأقفلــت اجللســة الســاعة الواحــدة وخمــس دقائــق وصلــى اهلل وســلم علــى‬\n                                               ‫نبينــا محمــد حــرر يف ‪1434/7/29‬ه ـ‬\n      ‫احلمــد هلل وحــده و يف يــوم الثالثــاء ‪1434/8/16‬ه ـ الســاعة الثانيــة‬\n      ‫عشــرة وفيهــا حضــر املدعــي العــام‪ .... /‬ولــم يحضــر املدعــى عليــه ‪.... /‬‬\n      ‫رغــم طلــب حضــوره مبوجــب خطابنــا رقــم ‪ 34/15278‬وتاريــخ‬\n      ‫‪1434/8/1‬ه ـ لــذا رفعــت اجللســة لطلــب حضــوره وتأجلــت إلــى يــوم‬\n      ‫االثنــن ‪1434/10/12‬ه ـ وأقفلــت اجللســة الســاعة الثانية عشــرة وخمس‬\n      ‫دقائــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/8/16‬ه ـ‬\n\n\n‫‪231‬‬\n\f‫احلمــد هلل وحــده‪ ،‬وبعــد ويف يــوم االثنــن ‪1434/10/12‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام‪ .........../‬وحضــر حلضــوره املدعــى عليــه ‪ ،.........../‬وبســؤال املدعى‬\n‫عليــه احلاضــر عــن إجابتــه التــي اســتمهل مــن أجلهــا قدم مذكــرة جوابية‬\n‫مكونــة مــن خمــس صفحــات ونصهــا حرفي ـ ًا مــا يلــي‪( :‬أقــدم لكــم‬\n‫الئحــة جوابيــة مقدمــة منــي أنــا املدعــى عليــه ‪ - ....... /‬رد ًا منــي علــى‬\n‫الدعــوى املقامــة ضــدي مــن هيئــة التحقيــق واالدعــاء العــام ‪ -‬فأقــول‬\n‫وبــاهلل التوفيــق ‪ :‬بعــد قراءتــي لالئحــة الدعــوى العامــة املقدمــة مــن هيئــة‬\n‫التحقيــق واالدعــاء العــام برقــم ) بــدون ( وتاريــخ ) بــدون) !!! فأنــى أجيب‬\n‫عليهــا مبــا يلــي ‪ -:‬أو َال ‪ -:‬لــم تتضمــن الئحــة الدعــوى العامــة رقــم وال‬\n‫تاريــخ القضيــة لــدى فــرع هيئــة التحقيــق واالدعــاء العــام قبــل إحالتهــا‬\n‫للمحكمــة اجلزائيــة املتخصصــة ‪ ،‬فأطلــب مــن فضيلتكــم رصد رقمها‬\n‫وتاريخهــا بالضبــط ملــا يف ذلــك مــن االســتدالل يف صحــة توجيــه االتهــام‬\n‫لــي بهــذه القضيــة مــن عدمــه وذلــك ملعرفــة هــل هــذه الدعــوى العامــة‬\n‫كانــت قبــل أو بعــد دعــواي بــرد االعتبــار والتــي قدمتهــا لديــوان املظالــم‬\n‫عمــا حصــل لــي مــن ســجن بــا تهمــة أوحكــم وكذلــك ضبــط جميــع ما‬\n‫جــاء بدعــوى املدعــي كاملــة بالنــص وهــو مالــم يتــم ضبطــه باجللســة‬\n‫األولــى ‪ .‬ثاني ـ َا ‪ -:‬مخالفــة إجــراءات القبــض والتحقيــق والســجن‬\n‫ألحــكام الشــرع والنظــام ‪-:‬حيــث تنــص املــادة الثامنــة والثمانــون بعــد‬\n‫املائــة مــن نظــام اإلجــراءات اجلزائيــة ( أن كل إجــراء مخالــف ألحــكام‬\n‫ا )‪.‬‬ ‫الشــريعة اإلســامية ‪ ،‬أو األنظمــة املســتمدة منهــا يكــون باط ـ ً‬\n‫وبتدقيــق النظــر يف الدعــوى املقدمــة بــن أيديكــم يتبــن لنــا جميعــا أن‬\n‫االتهامــات الصــادرة ضــدي جملــة تخالــف يف ظاهرهــا وباطنهــا للشــريعة‬\n\n\n                                                                                       ‫‪232‬‬\n\f      ‫اإلســامية ويتمثــل ذلــك يف محاولــة الوصــول إلــى إجــراءات إثبــات غيــر‬\n      ‫مشــروعة ‪ ،‬وهــو مخالــف ألحــكام الشــرع ‪ ،‬وملــواد النظــام رقــم ‪40 ،‬‬\n      ‫‪ 52 ، 141 ،، 46 ، 35 ،‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬ثالثـ ًا ‪ -:‬أنفــي‬\n      ‫نفيــا قاطعــا مــا نســب لــي مــن جــرم وتخزيــن مــا مــن شــأنه املســاس‬\n      ‫بالنظــام العــام عــن طريــق شــبكة االنترنــت ومــن جــرم متابعــة مــا يســمى‬\n      ‫مبنتــدى ‪ ....‬وتأثــري بأفــكاره فأنــا لــم أخــزن بــأي مــن جهــاز لــي مــا ميــس‬\n      ‫النظــام العــام ولــم أتابــع أي منتــدى ‪.‬أمــا مــا أســتدل بــه املدعــي العــام ممــا‬\n      ‫جــاء بأقوالــي املدونــة يف دفتــر التحقيــق ومــا جــاء بنتائــج فحــص أجهــزة‬\n      ‫احلاســب اآللــي املضبوطــة لديهــم فأقــول لــم يســمح لــي باالطــاع علــى‬\n      ‫دفتــر التحقيــق ولكــن إن كان مضمونــه مــا ذكــره املدعــي العــام يف‬\n      ‫الئحتــه عمــا أقــررت بــه حتقيقــا باســتجوابي فذلــك ال يثبــت إطالقــا‬\n      ‫صحــة مــا نســب لــي مــن قــول فــا يوجــد دليــل شــرعي أو نظامــي يجــرم‬\n      ‫مشــاهدة مقاطــع فيديــو بنهايــة األســبوع أو باإلجــازات حلــب االســتطالع‬\n      ‫املتضمنــة أفــام مناظــرات ومقاطــع عســكرية ال أذكرهــا ‪،‬علمـ َا بــأن‬\n      ‫جهــاز احلاســب املذكــور هــو خــاص بابنــي ‪ ......‬وقــد نســبته إلــي خوف ـ ًا‬\n      ‫علــى ابنــي أن يصــاب باجلنــون مبجــرد إحضــاره إليهــم حيــث كان يبلــغ‬\n      ‫الرابعــة عشــرة مــن عمــره ‪ -‬وقــد هددونــي بإحضــاره والتحقيــق معــه‬\n      ‫فاعترفــت مبــا يريــدون كــي ال ميــس ابنــي بســوء ًا ثــم ملــاذا ال يعاقــب مــن‬\n      ‫يشــاهدون مثــل هــذا بالقنــوات الرســمية والدوليــة والتــي تبــث بــن فتــرة‬\n      ‫وأخــرى مثــل هــذه املقاطــع العســكرية وأشــد مــن ذلــك بــل قــد يعرضــون‬\n      ‫ا عــن العمليــات العســكرية وأمــام مــرأى مــن ماليــن‬               ‫برنامج ـ ًا كام ـ ً‬\n      ‫ان جميــع املشــاهدين بــأن لهــم توجــه ميــس بالنظــام‬   ‫املشــاهدين فهــل َسـ ُـي َد ُ‬\n      ‫العــام ؟ أم تــدان تلــك القنــوات ببثهــا والتــي لم تبــث إال بإذن من احلكومة‬\n\n\n‫‪233‬‬\n\f‫ـاء االنتقــاء يف االســتدالل فلمــاذا مثــا لــم يتهمنــي‬   ‫؟ فــا يصــح قضـ َ‬\n‫املدعــي العــام بأننــي ‪ . ....‬إضافــة إلــى أنــه ال يصــح اتهــام أي شــخص‬\n‫باململكــة بتهمــة اطالعــه علــى مواقــع ألن كل املواقــع مســموحا‬\n‫باالطــاع عليهــا مــن قبــل مدينــة امللــك عبــد العزيــز للعلــوم والتقنيــة إال‬\n‫مــا كان محظــور ًا فــا تســتطيع فتحــه وإن كانــت هــذه هــي التهمــة‬\n‫احلقيقيــة فهــي تصنــف ضمــن اجلرائم املعلوماتية التــي تنظرها احملكمة‬\n‫اجلزائيــة وليســت احملكمــة اجلزائيــة املتخصصــة فأطلــب إحالتهــا إلــى‬\n‫جهــة االختصــاص ‪ .‬رابع ـ َا ‪ -:‬الفســاد يف االســتدالل ويتمثــل يف النقــاط‬\n‫التاليــة ‪ -:‬االعتمــاد يف اإلدانــة علــى اإلقــرار املنســوب إلــي حيــث أدعــى‬\n‫املدعــي العــام أنــى ارتكبــت العديــد مــن اجلرائــم وأنــي قــد أقــررت عليهــا‬\n‫وأنــا يف كامــل إدراكــي ووعيي ومنها متابعتــي ملنتديات‪ ........‬وتخزيني‬\n‫علــى احلاســوب لبعــض مقاطــع الفيديــو ‪ .......‬و‪ ....... .‬وهــذا الــكالم‬\n‫مــردود عليــه بأنــي لــم أعتــرف بــأي مــن التهــم التــي وجهــت لــي ولــم يوجــد‬\n‫علــى حاســوبي أي مــن تلــك املقاطــع التــي يزعــم املدعــي العــام ضبطهــا‬\n‫على احلاسوب املصادر وال يوجد دليل واحد يثبت ذلك ‪ ،‬أما بخصوص‬\n‫نتائــج فحــص أجهــزة احلاســب اآللــي املضبوطــة فلــم اطلــع أيضــا علــى‬\n‫تلــك النتائــج ولكــن إن كان مضمونهــا كمــا ذكــره املدعــي العــام يف‬\n‫الئحتــه بأنــه بتفتيــش منزلــي ضبــط جهازيــن حاســب آلــي محمــول‬\n‫وبتفتيشــهما وفحصهمــا تبــن احتوائهمــا علــى مقاطــع ‪.....‬الــخ فهــذا غيــر‬\n‫صحيــح وال يــدل إطالقــا علــى مــا ادعــى بــه املدعــي العــام مــن تخزينــي‬\n‫بشــبكة االنترنــت أو بجهــازي مــا ميــس النظــام العــام فلــم أخزن أو أنســخ‬\n‫أو أنشــر بجهــازي شــيء ممــا ذكــر ودليــل ذلــك أنهــم ســلموني أجهزتــي‬\n‫وأجهزة أهلي وأوالدي التي لديهم بعد خروجي من الســجن وبخصوص‬\n\n\n                                                                                        ‫‪234‬‬\n\f      ‫تصفحــي علــى االنترنــت فــا أنكــر ذلــك فلقــد شــاهدت بعــض اخلطــب‬\n      ‫واملواعــظ الدينيــة لألئمــة العــدول أهــل الســنة ممــن يأمــرون باخليــر‬\n      ‫ويحثــون علــى طاعــة اهلل ورســوله وأولــي األمــر ‪ ،‬وال يوجــد يف الشــرع‬\n      ‫وال يف األنظمــة بجملتهــا نــص واحــد يحــرم املشــاهدة واالطــاع املنضبط‬\n      ‫بضوابــط الشــرع ‪ ،‬وأنــا لــم أتعــد نطــاق الشــرع ولــم أخالــف النظــام ولــم‬\n      ‫أســمح ملســامعي وبصــري أن يشــاهدا ويســمعا ألقــوال اخلارجــن عــن‬\n      ‫النظــام والداعــن للخــروج علــى ولــى اآلمــر فهــو ولــي أمــري ‪ ،‬ولــه يف‬\n      ‫عنقــي بيعــة ‪ ،‬كمــا أن أخــذ ناظــر القضيــة بجميــع اعترافاتــي املدونــة‬\n      ‫قبــل إحالــة هــذه القضيــة لفضيلتــه وعــدم أخــذه مبــا صــدر منــي أمــام‬\n      ‫فضيلتــه باملجلــس القضائــي مــن عــدم مصادقتــي علــى بعــض مــا ورد‬\n      ‫بتلــك االعترافــات هــو مخالــف للمــادة (‪ )104‬مــن نظــام املرافعــات‬\n      ‫ا أمــام‬      ‫الشــرعية التــي نصــت علــى أنــه ( يجــب أن يكــون اإلقــرار حاصـ ً‬\n      ‫القضــاء أثنــاء الســير يف الدعــوى املتعلقــة بالواقعــة املقــر بهــا ) حيــث أن‬\n      ‫اإلقــرارات املنســوبة إلــي لــم أصــادق عليهــا أمــام ناظــر القضيــة خــال‬\n      ‫فتــرة ســجني وهــذا مخالــف للنظــام ‪ ،‬وأمــا توقيعــي فقــد حصــل حتــت‬\n      ‫وطــأة اإلكــراه ‪ ،‬وإن كنــت ال أســتطيع إثباتــه إال أنــه أمــر معــروف‬\n      ‫لــدى جهــات التحقيــق وتلــك االعترافــات املدونــة محــل نظــر ‪.‬خامسـ َا ‪-:‬‬\n      ‫يجــب أن يصــدر اإلقــرار عــن إرادة حــرة وبــدون إكــراه ‪ :‬يقــول اهلل‬\n      ‫كـ ِـر َه َوقَ ْل ُبـ ُه ُم ْط َم ِئـ ٌّـن‬                                                   ‫ك َفـ َـر ِبـ ّ ِ‬\n                                               ‫ـالل مِ ــن َب ْعــدِ إ َميا ِنـ ِه ِإ َّال َمــنْ ُأ ْ‬               ‫((مــن َ‬\n                                                                                                                          ‫تعالــى ‪َ :‬‬\n                     ‫ـب ِّمـ َـن ّ ِ‬\n      ‫الل َو َل ُهـ ْـم‬                ‫ك ْفـ ِـر َصــدْ ًرا َف َع َل ْي ِهـ ْـم غَ َضـ ٌ‬   ‫َكــن َّمــن َشـ َـر َح ِبا ْل ُ‬\n                                                                                                                         ‫ِبا ِإل َميــانِ َول ِ‬\n      ‫اب َع ِظيــم )) فاإلقــرار الصــادر حتــت تأثيــر اإلكــراه باطــل ‪ ،‬حتــى‬                                                 ‫َعـ َـذ ٌ‬\n      ‫ولــو قامــت الدالئــل علــى صحتــه فقــد كنــت واقعـ ًا حتــت تأثيــر اإلكراه‬\n      ‫‪ ،‬فلــم أكــن يف حــال آمــن فيهــا علــى نفســي وحياتــي منهــم ‪ .‬فكيــف‬\n\n\n‫‪235‬‬\n\f‫بابنــي وفلــذة كبــدي ويؤيــد ذلــك مــا ذهــب إليــه أميــر املؤمنــن عمــر بــن‬\n‫اخلطــاب رضــي اهلل عنــه حــن قــال « ليــس الرجــل بأمــن مــع نفســه إذا‬\n‫جوعتــه أو ضربتــه أو أوثقتــه « فعبــارة املكــره الغيــة ‪ ،‬وال ينشــأ بهــا‬\n‫عقــد وال يترتــب عليهــا حكــم ‪ ،‬ألن اإلكــراه يفســد االختيــار والرضــا‬\n‫‪ ،‬وإذا فســد االختيــار انعــدم القصــد وبطــل األثــر فاإلكــراه علــى‬\n‫الــكالم ال يجــب بــه شــيء ألن املكــره غيــر مكلــف ‪ ،‬وهــو إن نطــق‬\n‫بكلمــة الكفــر فإنــه غيــر مؤاخــذ بهــا ‪ ،‬وإذا قــذف غيــره فــا يقــام‬\n‫عليــه حــد القــذف ‪ ،‬ولــو أقــر ال يؤخــذ بإقــراره وعليــه ال يعــول علــى هــذا‬\n‫اإلقــرار كدليــل وعــدم األخــذ بــه أو التعويــل عليــه يف اإلدانــة ‪.‬وخالصــة‬\n‫مــا ســبق فــإن اإلكــراه الواقــع هنــا مخالــف إلحــكام الشــرع ولألنظمــة‬\n‫‪ ،‬واملخالفــة ذاتهــا تنطبــق علــى إحلــاق التهــم بــي بــدون مســوغ وبــدون بينــة‬\n‫أو دليــل والتــي تتمثــل يف االدعــاء علــي بتخزيــن مقاطــع تســعى لهــدم‬\n‫النظــام ‪ -‬فالشــريعة ومــن ثــم القضــاء لــم يعــوال علــى االعتــراف واإلقــرار‬\n‫علــى الرغــم مــن أنــه دليــل قــوي علــى اإلدانــة وذلــك لصــدوره حتــت تأثيــر‬\n‫اإلكــراه ‪ ،‬وســير ًا علــى هــدي الشــريعة اإلســامية الغــراء ثــم نــص املــادة‬\n‫( ‪ ) 188‬مــن نظــام اإلجــراءات اجلزائيــة فــإن البطــان هــو اجلــزاء املترتــب‬\n‫علــى تلــك االنتهــاكات وعلــى الفســاد يف االســتدالل والقصــور يف‬\n‫التســبيب ألن مــا بنــى علــى باطــل فهــو باطــل‪ .‬سادسـ َا ‪ /‬اخلطــأ يف تطبيــق‬\n‫النظــام وتأويلــه ‪ -:‬فلقــد أنتهــك ضبــاط املباحــث واملدعــى العــام كل‬\n‫أحــكام النظــام وراحــوا يفنــدون التهــم واألباطيــل واضعــن نصــوص‬\n‫األنظمــة حتــت أقدامهــم ‪ ،‬ممــا يصنــف كل أفعالهــم بالبطــان ‪ ،‬فــإذا‬\n‫كان الفعــل النــاجت عنــه البطــان قــد نــص عليــه يف النظــام بــأي مــن‬\n‫صيغتــي األمــر أو النهــي اجلازمتــن فــا يجــوز التحايــل عليهمــا والقضــاء‬\n\n\n                                                                                        ‫‪236‬‬\n\f      ‫بصحــة األجــراء وال ســيما وإن كان البطــان احلاصــل ممــا ال يجــوز‬\n      ‫تصحيحــه أو تداركــه وتــدارك آثــاره ‪ .‬ومــا يقطــع بصحــة ذلــك أن أميــر‬\n      ‫املؤمنــن عمــر بــن اخلطــاب رضــي اهلل عنــه قــد أنتهجــه وأقــره بــل وعمــل‬\n      ‫بــه حيــث روي عــن عمــرو بــن قيــس ‪ ،‬عــن ثــور الكنــدي أن عمــر بــن‬\n      ‫اخلطــاب رضــي اهلل عنــه كان يتجــول باملدينــة ليــا ‪ ،‬فســمع صــوت‬\n      ‫رجــل يف بيــت يتغنــى ‪ ،‬فتســور عليــه ‪ ،‬فوجــد عنــده امــرأة وعنــده خمــر ‪،‬‬\n      ‫فقــال ‪ :‬يــا عــدو اهلل أظننــت أن اهلل يســترك وأنــت علــى معصيتــه ؟ فقال‪:‬‬\n      ‫وأنــت يــا أميــر املؤمنــن ال تعجــل علــي‪ ،‬إن أكــن عصيــت اهلل واحــدة‬\n      ‫فقــد عصيــت اهلل يف ثــاث‪ ...‬قــال تعالى ‪( :‬وال جتسســوا) وقد جتسســت‬\n      ‫‪ ،‬وقــال اهلل عــز وجــل‪( :‬وليــس البــر بــأن تأتــوا البيــوت مــن ظهورهــا)‬\n      ‫وقــد تســورت علــي ‪ ،‬ودخلــت علــي مــن ظهــر البيــت بغيــر إذن‪ .‬وقــال اهلل‬\n      ‫عــز وجــل‪( :‬ال تدخلــوا بيوتــا غيــر بيوتكــم حتــى تستأنســوا وتســلموا‬\n      ‫علــى أهلهــا) فقــد دخلــت بغيــر ســام‪ .‬قــال عمــر رضــي اهلل عنــه‪ :‬فهــل‬\n      ‫عنــدك مــن خيــر إن عفــوت عنــك ؟ قــال ‪ :‬نعــم‪ ...‬واهلل يــا أميــر املؤمنــن‬\n      ‫لئــن عفــوت عنــي ال أعــود ملثلهــا أبــدا ‪ ،‬قــال ‪ :‬فعفــا عنــه وخــرج وتركــه‬\n      ‫‪ .-‬فهــل خالــف هنــا أميــر املؤمنــن عمــر رضــي اهلل عنــه أحــكام الشــرع‬\n      ‫أم أعطــى لنــا التصــور القضائــي احلقيقــي لإلجــراءات التــي ال منــاص من‬\n      ‫األخــذ بهــا وتطبيقهــا لعــدم مخالفــة أوامــر اهلل عــز وجــل وآياتــه‬\n      ‫وأحكامــه وكفــى بذلــك شــاهدا ودليــا علــى األســلوب األمثــل لألمــر‬\n      ‫باملعــروف والنهــي عــن املنكــر وتوضيح ـ ًا ملــا يجــب أن تكــون عليــه‬\n      ‫نصــوص النظــام الوضعــي وقــد راعــى املشــرع الوضعــي ذلــك يف وضعــه‬\n      ‫والســبل‬\n           ‫لنصــوص نظــام اإلجــراءات اجلزائيــة فوضــع القواعــد والقيــود ُ‬\n      ‫التــي ُتنظــم دخــول البيــوت والقبــض علــى األشــخاص وتفتيشــهم وتفتيش‬\n\n\n‫‪237‬‬\n\f‫مســاكنهم واالطــاع علــى محارمهــم وعــورة مســاكنهم ‪ ..‬فجاءت كل‬\n‫النصــوص يف النظــام بصيغــة األمــر أو النهــي وقــد خالــف ضبــاط‬\n‫املباحــث وقــوات الطــوارئ واالدعــاء العــام كل ذلــك وجتنــوا علــى‬\n‫النظــام وخالفــوا املــواد ‪ 34‬و ‪ 119 ، 116 ، 114 ، 113 ، 35‬وغيرهــا‬\n‫مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬وكل أمــر بنــى علــى باطــل فهــو باطــل‪.‬‬\n‫ســابع َا ‪ /‬عــدم وجــود بينــه أو دليــل إدانــة ‪ -:‬ذكــر املدعــي العــام بدعــواه‬\n‫أن القبــض علــي مت ( إثــر توفــر معلومــات مفادهــا قيامــه بدعــم اجلماعات‬\n‫املســلحة يف دولــة اليمــن ) فلــم يــرد بالئحــة املدعــي العــام مــا يؤيــد صحــة‬\n‫ســبب الق ــبض علي ‪ ،‬ل ــذا أطلب من فضيلتكم مناقشــته بذلك ورصد‬\n‫مــا يجيــب بــه بالضبــط وإجــراء املوجــب الشــرعي حيالــه فهــذا اتهــام‬\n‫باطــل وإال كيــف تقبضــوا علــي ألجــل معلومــات باطلــة ثــم حــن طالبــت‬\n‫ببراءتــي تتهمونــي بتهمــة غيــر التــي قبضتــم علــي بســببها بزعمكــم ومــا‬\n‫هــذا التخبــط إال بســبب ظلمكــم فإلــى اهلل املشــتكى وحســبي اهلل‬\n‫ونعــم الوكيــل فأطلــب إثباتهــم لهــذه التهمــة التــي بســببها قبضــوا علــي‬\n‫والتــي لــم أعلــم بهــا إال بعــد خروجــي مــن الســجن واســتالمي لصحيفــة‬\n‫دعواهــم ؟ ومــن ذلــك عــدم إقامــة دليــل علــى صحــة وقــوع أفعــال ماديــة‬\n‫تعــد جرميــة أو تنفــى وقوعهــا بالطــرق التــي حددهــا النظــام ‪ ،‬ولــم يســتند‬\n‫املدعــي العــام يف اتهاماتــه لــي علــى أي دليــل أو إقــرار معتبــر شــرعا أو‬\n‫نظام ـ ًا ‪ ،‬واألصــل هــو بــراءة الذمــة وانشــغالها عــارض وال يجــوز توقيــع‬\n‫عقوبــة علــى املتهــم حتــى تثبــت إدانتــه ثبوتــا قطعيــا ال يقبــل الشــك أو‬\n‫الريبــة ‪ .‬فضيلــة القاضــي لقــد ورد يف نظــام املرافعــات الشــرعية يف املــادة‬\n‫‪ « 198‬ال يجــوز تنفيــذ األحــكام جبــرا قبــل اكتســاب احلكــم القطعيــة‬\n‫« فمــا بــال فضيلتكــم بعــدم صــدور حكــم أصــا مــن القضــاء بإدانتــي‬\n\n\n                                                                                        ‫‪238‬‬\n\f      ‫بتهمــة محــددة ‪ ،‬وكمــا هــو ثابــت فــإن املتهــم بــريء حتــى تثبــت إدانتــه‬\n      ‫وعليــه فــا يجــوز عقوبتــه إال بحكــم قطعــي لــذا آمــل مــن فضيلتكــم‬\n      ‫الوقــوف علــى تلــك األســانيد التــي قدمتهــا لفضيلتكــم واالســتيثاق‬\n      ‫منهــا‪ .‬ثامنـاً‪ /‬بطــان مطالبــة املدعــي العــام بعقوبتــي اســتنادا لنصــوص‬\n      ‫األنظمــة‪ -:‬جــل مــا تقــدم بــه املدعــي العــام مطالبــا بعقوبتــي بالعقوبــة‬\n      ‫املنصــوص عليهــا باملــادة (‪ )6‬مــن نظــام مكافحــة جرائــم املعلوماتيــة‬\n      ‫واحلكــم مبنعــي مــن الســفر اســتنادا للمــادة (‪ )6‬مــن الفقــرة الثانيــة مــن‬\n      ‫نظــام وثائــق الســفر كلهــا بنيــت علــى أدلــة واهيــة وليــس لهــا وجــود مــن‬\n      ‫الناحيــة الفعليــة والواقعيــة ألن اإلجــراء الباطــل يترتــب عليــه البطــان‬\n      ‫فيمــا يليــه وذلــك كمــا ســبق وأن بينــاه يف تفنيــد احلجــج علــى براءتــي‬\n      ‫‪،‬ليــس هــذا فحســب بــل خروجــي مــن الســجن لعــدم ثبــوت دليــل إدانــة‬\n      ‫ضــدي بعــد املــدة التــي قضيتهــا يبــن لنا بجــاء تأكيد براءتــي وتأكيد‬\n      ‫بطــان اإلجــراءات التــي مت انتهاكهــا مــن قبــل املباحــث والطــوارئ‪.‬‬\n      ‫وبخصــوص املــادة (‪ )6‬مــن نظــام مكافحــة جرائــم املعلوماتيــة فهــذا‬\n      ‫مــردود عليــه بعــدم وجــود دليــل مــادي أو معنــوي ضــدي‪ ،‬حيــث لــم يثبــت‬\n      ‫إنتاجــي أو تخزينــي أو إرســالي ألي مــادة معلوماتيــة مــن شــأنها املســاس‬\n      ‫بالنظــام العــام أو أنشــاء مواقــع علــى الشــبكة العنكبوتيــة ‪........‬الــخ ‪،‬‬\n      ‫وبخصــوص الفقــرة الثانيــة مــن املــادة (‪ )6‬مــن نظــام وثائــق الســفر التــي‬\n      ‫يطلــب املدعــى العــام بتطبيــق نصوصهــا وأحكامهــا علــي فقــد نصــت‬\n      ‫هــذه املــادة علــى أنــه « ال يجــوز املنــع مــن الســفر إال بحكــم قضائــي أو‬\n      ‫بقــرار يصــدره وزيــر الداخليــة ألســباب محــددة تتعلــق باألمــن و ملــدة‬\n      ‫معلومــة ‪ ،‬و يف كلتــا احلالتــن يبلــغ املمنــوع مــن الســفر يف فترة ال تتجاوز‬\n      ‫أســبوع ًا مــن تاريــخ صــدور احلكــم أو القــرار مبنعــه مــن الســفر» فهــذا‬\n\n\n‫‪239‬‬\n\f‫مــردود عليــه بعــدم صــدور حكــم قضائــي ضــدي لكونــي لــم أقــدم‬\n‫للمحاكمــة مــن أساســه ولــم يصــدر حكــم قضائــي ضــدي ولــم يصــدر‬\n‫أيضــا أي قــرار مــن قبــل الداخليــة ضــدي لعــدم وجــود دليــل إدانــة واحــد‬\n‫يثبــت مــا اســتند إليــه املدعــي العــام ‪،‬وللعلــم فإنهــم يعلمــون أن جــواز‬\n‫ســفري منتهــي منــذ خمســة عشــرة ســنة ولــم أســافر خــارج بلــدي فلمــا‬\n‫يطالبــوا مبنعــي ؟ ! وإن كان حقــا مــا يدعيــه ضــدي ملــا خرجــت مــن‬\n‫الســجن لعــدم ثبــوت إدانتــي ولظللــت فتــرة طويلــة بــن جــدران الســجن‬\n‫‪،‬ولكــن احلــق حتمــا ســيظهر بجــاء مهمــا طــال ليلــه‪ .‬وختامــا‪ /‬فــإذا‬\n‫كان القاضــي هــو حاكــم القضيــة وأســتاذها وله ســلطات وصالحيات‬\n‫شــبه مطلقــة للتعامــل مــع القضيــة ووســائل اإلثبــات حيــث أن القاضــي‬\n‫لــن يرضــى أو يقبــل يف قبولــه للطــرق غيــر املشــروعة أو امللتويــة وهــو‬\n‫األمــر ذاتــه الــذي فعلــه أفــراد وضبــاط املباحــث والطــوارئ و هيئــة‬\n‫التحقيــق واالدعــاء العــام و فيمــا ينســب لــي مــن أقــوال ومزاعــم فليــس‬\n‫للقاضــي أن يبنــي حكمــه وقناعتــه إال وفقــا ملــا ينــص عليــه الشــرع أو‬\n‫النظــام املعتبــر‪ .‬والــذي عليــه احملققــن مــن العلمــاء أنــه ال يجــوز للقاضــي‬\n‫أن يبنــى حكمــة علــى علمــه الشــخصي مهمــا كان صحيحــا ويجــب‬\n‫عليــه أن يؤسســه علــى األدلــة املطروحــة أمامــه يف الدعــوى ويســببه‬\n‫ليتســنى االعتــراض علــى احلكــم بطريــق االســتئناف ‪ ،‬فالعقوبــات‬\n‫الشــرعية علــى اختالفهــا وتنوعهــا مــن حيــث التغليــظ والتخفيــف‪ ،‬ال‬\n‫يشــك مســلم بــأن حكــم اهلل صالــح لــكل زمــان ومــكان بــل ومصلــح‬\n‫لــه إال أن فرضهــا دون إعمــال نظــام إجرائــي ينتــج عنــه حتمــا وبــكل‬\n‫بســاطة اســتبدادا وحتكمــا وتضحيــة بأهــم حقــوق األفــراد وحريتهــم‬\n‫العامــة ويترتــب عليــه ظلــم وجــور مقيــت فيســهل معاقبــة البــريء ويبــرأ‬\n\n\n                                                                                       ‫‪240‬‬\n\f      ‫اجلانــي فحــق الدولــة يف توقيــع العقــاب باجلنــاة جــزاء وفاقــا ملــا اقترفتــه‬\n      ‫أيديهــم بحــق املجتمــع ال يكــون تلقائيــا أو تعســفيا إمنــا يتــم وفــق قنــوات‬\n      ‫إجرائيــة حددهــا الشــرع والنظــام وألــزم جهــات التحقيــق والقضــاء‬\n      ‫بالتقيــد مبــا جــاء بهــا واهلل أعلــم ‪.‬هـ ــذا جوابــي وبنــاء عليــه أطلــب مــن‬\n      ‫فضيلتكــم مــا يلــي ‪ :‬أو َال ‪ :‬ضبــط مــا جــاء بالئحــة االتهــام وضبــط‬\n      ‫جوابــي عليهــا وضبــط رد املدعــي العــام علــى جوابــي بالنــص وخصوصـ ًا‬\n      ‫ســبب القبــض علــي وإجــراء الوجــه الشــرعي حيالــه ‪.‬ثانيــا ‪ :‬احلكــم‬\n      ‫ببراءتــي مــن التهــم املنســوبة إلــي ‪.‬ثالث ـ ًا ‪ :‬رد اعتبــاري ‪.‬وجزاكــم اهلل‬\n      ‫خيــر َا وســدد خطانــا وخطاكــم ‪ .‬مقدمــه ‪ ................ /‬رقــم الســجل‬\n      ‫املدنــي ‪.............. /‬اجلــوال ‪ ..../‬انتهــى‪ .‬هكــذا أجــاب‪ ،‬وبعــرض ذلــك‬\n      ‫علــى املدعــي العــام رد قائ ـاً‪ :‬تضمــن جــواب املدعــى عليــه إنــكاره ملــا‬\n      ‫نســب إليــه يف الئحــة الدعــوى العامــة وهــذا غيــر صحيــح بــل الصحيــح‬\n      ‫مــا جــاء يف الئحــة الدعــوى العامــة وبينتــي علــى ذلــك األدلــة املشــار إليهــا‬\n      ‫يف الالئحــة واملرفقــة يف أوراق القضيــة وأطلــب الرجــوع إليهــا وأمــا مــا‬\n      ‫ذكــره املدعــى عليــه مــن بطــان اإلجــراءات املتخــذة يف هــذه القضيــة‬\n      ‫فــإن األصــل يف اإلجــراءات الصحــة والســامة‪ ،‬ولــم يظهــر لالدعــاء‬\n      ‫العــام عنــد دراســته للقضيــة وال فيمــا قدمــه املدعــى عليــه يف جوابــه مــا‬\n      ‫يبطــل هــذه اإلجــراءات‪ ،‬وأمــا مــا ذكــره املدعــى عليــه مــن تعرضــه‬\n      ‫لإلكــراه فــإن دعــوى اإلكــراه التــي يدعيهــا املدعــى عليــه ال بينــة‬\n      ‫عليهــا‪ ،‬واملدعــى عليــه أقــر حتقيق ـ ًا ووقــع وبصــم علــى دفتــر التحقيــق‬\n      ‫وهــو مســئول عمــا جــاء فيــه ألن دفاتــر التحقيــق تعتبــر مــن احملــررات‬\n      ‫الرســمية وال يجــوز الطعــن فيهــا إال بالتزويــر‪ ،‬وبينتــي علــى الدعــوى مــا‬\n      ‫جــاء يف أقوالــه حتقيقــا املرفقــة علــى اللفــة رقــم (‪ )9‬يف الصفحــة رقــم‬\n\n\n‫‪241‬‬\n\f‫(‪ )18‬حيــث أقــر حتقيق ـ ًا بأنــه تعــرف علــى موقــع ‪ ....‬علــى الشــبكة‬\n‫املعلوماتيــة (اإلنترنــت) بإجــازة عيــد الفطــر ‪1430‬ه ـ كمــا كان يــزور‬\n‫بعــض املواقــع مثــل ‪ .....‬وجميعهــا كان يشــاهدها حلــب االســتطالع‬\n‫فقــط‪ ،‬و بينتــي األخــرى تقريــر فحــص املضبوطــات رقــم (‪-51-171‬‬\n‫‪ )31-17-56767‬املرفــق باللفــات رقــم (‪ )16‬و (‪ )13‬و (‪ )12‬و املتضمــن‬\n‫عــدد مــن مقاطــع الفيديــو تعــرض الهالــك ‪ ......‬و مقاطــع فيديــو‬\n‫تعــرض‪.....‬و مقاطــع صوتيــة كلهــا حتــث علــى املشــاركة يف القتــال و‬\n‫مقاطــع فيديــو لعمليــات عســكرية يف العــراق و الصومــال و ديالــى و‬\n‫زيــارة ملنتــدى ‪ ....‬و كذلــك مقطــع فيديــو بعنــوان (‪ )........‬يعــرض مــن‬\n‫خاللــه عمليــة عســكرية يف ‪ .............‬و كذلــك مقطــع فيديــو بعنــوان‬\n‫(‪ )....‬يتحــدث عــن املدعــو ‪ ....‬و يعــرض مــن خاللــه عمليــة عســكرية يف‬\n‫‪ ،...............‬هــذه هــي بينتــي و ليــس لــدي مزيــد عليهــا‪ ،‬هكــذا رد‪،‬‬\n‫وقــد جــرى اطالعنــا علــى أقــوال املدعــى عليــه حتقيقــا‪ ،‬وتقريــر فحــص‬\n‫املضبوطــات التــي أشــار إليهــا املدعــي العــام وهــي موافقــة ملــا ذكــره‬\n‫املدعــي العــام‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه رد بقولــه‪ :‬بالنســبة‬\n‫لألقــوال التــي ذكرهــا املدعــي العــام فهــي أقوالــي كتبتهــا بخــط يــدي‬\n‫و هــي مــن إمــاء الضابــط حيــث أخبرنــي بــأن هــذه احملتويــات وجــدت‬\n‫يف احلاســب اآللــي ولــم أر اجلهــاز ولــم يطلعنــي عليــه وقــد كتبــت ذلــك‬\n‫ألن ابنــي كان يســتخدم اجلهــاز فخشــيت أن يتــم اســتجوابه‪ ،‬و مضمــون‬\n‫هــذه األقــوال املذكــورة بعضــه صحيــح و بعضــه غيــر صحيــح‪ ،‬فمــا‬\n‫يتعلــق ‪ ....‬فلــم أطلــع عليهــا يف احلاســب اآللــي إطالقــا‪ ،‬ومــا ســوى ذلــك‬\n‫مــن املشــاهدات فصحيــح‪ ،‬و قــد أكرهــت علــى كتابــة هــذه األقــوال‬\n‫بهــذه الصيغــة كمــا ذكــرت يف جوابــي‪ ،‬علمــا بــأن اجلهازيــن املشــار‬\n\n\n                                                                                    ‫‪242‬‬\n\f      ‫إليهمــا لــم يكــن مخزنــا بهمــا أي مســتندات أو مقاطــع أو مشــاركات‬\n      ‫أو تعليقــات ســواء باســمي الصحيــح أو أســماء مســتعارة إطالقــا غايــة مــا‬\n      ‫فعلتــه هــو مشــاهدات ملناظــرات و كذلــك مشــاهدات ملوقــع ‪ ....‬وفــرق‬\n      ‫بني التخزين و املشــاهدة‪ ،‬وبالنســبة ملا ورد يف التقرير الفني بخصوص‬\n      ‫‪ ........‬فغيــر صحيــح‪ ،‬و طــوال عمــري بحمــد اهلل لــم أتابــع ‪ .. ...‬و أتبــرأ‬\n      ‫إلــى اهلل مــن منهجــه و منهــج كل مــن خــرج عــن أهــل الســنة واجلماعــة‪،‬‬\n      ‫وبالنســبة للمقاطــع الصوتيــة لألناشــيد فلــم أقــم بتخزينهــا وإمنــا قــام‬\n      ‫الفنــي بتخزيــن برامــج و مــن ضمنهــا أناشــيد إســامية علــى اجلهــاز بعــد‬\n      ‫عمــل صيانــة لــه يف أحــد محــات صيانــة احلواســب اآلليــة دون أن أطلــب‬\n      ‫منــه ذلــك ولــم أســمع هــذه األناشــيد و الــذي يســمعها هــو ابنــي‪ ،‬هكــذا‬\n      ‫رد‪ ،‬وبعــرض ذلــك علــى املدعــي العــام رد بقولــه‪ :‬هــذه امللفــات مخزنــة يف‬\n      ‫جهــاز احلاســب اآللــي و هــذا مــا يثبتــه التقريــر الفنــي املشــار إليــه و أمــا‬\n      ‫منتــدى ‪ ....‬فقــد أثبــت التقريــر أنهــا زيــارة لهــذا املنتــدى‪ ،‬هكــذا رد‪ ،‬و‬\n      ‫رد املدعــى عليــه قائــا‪ :‬ممــا يــدل علــى براءتــي أن جهــازي احلاســب اآللــي‬\n      ‫ســلما لــي بعــد خروجــي مــن الســجن ولــو كانــت حتتــوي علــى مــا يديننــي‬\n      ‫ملــا ســلما لــي‪ ،‬و أؤكــد علــى أننــي لــم أقــم بفعــل أي تخزيــن مقصــود‬\n      ‫علــى احلاســب اآللــي‪ ،‬علمــا بأنــه قــد ذكــر يف الالئحــة بــأن ســبب‬\n      ‫القبــض علــي ليــس جلرائــم معلوماتيــة و إمنــا لــورود معلومــات مفادهــا‬\n      ‫القيام بدعم اجلماعات املســلحة يف دولة ‪ ..............‬كما ورد يف الالئحة‬\n      ‫ولــم يثبــت علــي هــذا األمــر بعــد أن روجعــت جميــع حســاباتي البنكيــة و‬\n      ‫بالتالــي لــم أتهــم يف الالئحــة بهــذه التهمــة‪ ،‬هكــذا رد‪ ،‬ورد املدعــي‬\n      ‫العــام قائــا‪ :‬لــم يتــم توجيــه االتهــام للمدعــى عليــه بدعــم اجلماعــات‬\n      ‫املســلحة يف اليمــن و إمنــا مت توجيــه االتهــام لــه بالتهــم املوجــودة يف الئحــة‬\n\n\n‫‪243‬‬\n\f‫الدعــوى‪ ،‬هكــذا رد‪ ،‬و بســؤال الطرفــن هــل لديكمــا أي إضافــة‬\n‫غيــر مــا تقــدم؟ فقــاال‪ :‬ال‪ .‬لــذا جــرى قفــل بــاب املرافعــة‪ ،‬ورفعــت اجللســة‬\n‫للنطــق باحلكــم‪ ،‬وأقفلــت اجللســة الســاعة الثانيــة عشــرة والربع وتأجلت‬\n‫إلــى يــوم األحــد ‪1434/11/23‬ه ـ وصلــى اهلل علــى نبينــا محمــد حــرر يف‬\n                                                                   ‫‪1434/10/12‬هـ‬\n‫احلمــد هلل وحــده وبعــد‪ :‬اليــوم األحــد ‪1434/11/23‬ه ـ افتتحــت اجللســة‬\n‫الســاعة الواحــدة والربــع وفيهــا حضــر املدعــي العــام وحضــر حلضــوره‬\n‫املدعــى عليــه ‪ ،.................‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام‬\n‫وإجابــة املدعــى عليــه املتضمنــة إنــكاره ملــا اســند إليــه يف الدعــوى وأن‬\n‫احلاســب اآللــي يف املنــزل ويســتعمله أفــراد أســرته‪ ،‬ونظــرا إلــى أنــه لــم‬\n‫يقــم دليــل مســتقيم علــى أنــه هــو الــذي قــام بتخزيــن املــواد املشــار إليهــا‬\n‫يف تقريــر فحــص املضبوطــات‪ ،‬ومــن املقــرر أن الدليــل إذا تطــرق إليــه‬\n‫االحتمــال ســقط بــه االســتدالل‪ ،‬وأن األصــل بــراءة الذمــة‪ ،‬وأمــا مجــرد‬\n‫االطــاع عــن طريــق الشــبكة املعلوماتيــة فقــد جــاء يف اعترافــه حتقيقــا‬\n‫املرصــود بعاليــه أنــه كان بقصــد حــب االســتطالع‪ ،‬وملــا تقــرر فقهــا‬\n‫ونظامــا أن االعتــراف ال يتجــزأ علــى صاحبــه‪ ،‬كمــا لــم يقــم دليــل‬\n‫علــى أن املدعــى عليــه قــام بالدخــول علــى مواقــع محجوبــة والظاهــر أن‬\n‫املواقــع التــي اطلــع عليهــا متاحــة (غيــر محجوبــة) ولــكل مــا ســبق فلــم‬\n‫يثبــت إدانــة املدعــى عليــه مبــا أســند إليــه يف الدعــوى وأخليــت ســبيله‬\n‫منهــا لعــدم كفايــة الدليــل وبذلــك حكمــت‪ ،‬وأفهمــت املدعــى عليــه‬\n‫بــأن مطالبتــه بالتعويــض تكــون يف دعــوى مســتقلة بعــد اكتســاب‬\n‫االحــكام القطعيــة‪ ،‬وبإعــان احلكــم علــى الطرفــن قــرر املدعــى عليه‬\n‫قائــا‪ :‬أنــا قانــع باحلكــم‪ .‬هكــذا قــرر‪ ،‬كمــا قــرر املدعــي العــام قائال‪:‬‬\n\n\n                                                                                            ‫‪244‬‬\n\f      ‫أنــا معتــرض علــى احلكــم وأرغــب يف تقــدمي الئحــة اعتراضيــة‪ .‬هكــذا‬\n      ‫قــرر‪ ،‬فأفهمــت املدعــي العــام بــأن موعــد اســتالم نســخة مــن احلكــم‬\n      ‫يف يــوم الثالثــاء ‪1434/11/25‬ه ـ لتقــدمي اعتراضــه خــال ثالثــن يومـ ًا‬\n      ‫تبــدأ مــن تاريــخ االســتالم املذكــور وفقـ ًا للمــادة الرابعــة والتســعني بعــد‬\n      ‫املائــة مــن نظــام اإلجــراءات اجلزائيــة ويف حالــة انتهــاء املــدة دون تقــدمي‬\n      ‫اعتراضــه يتــم رفــع املعاملــة حملكمــة االســتئناف اجلزائيــة املتخصصــة‬\n      ‫بــدون الئحــة وفق ـ ًا للمــادة اخلامســة والتســعني بعــد املائــة مــن النظــام‬\n      ‫ســالف الذكــر وصلــى اهلل علــى نبينــا محمد حــرر يف ‪1434/11/23‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1434/11/25‬ه ـ فتحــت اجللســة‬\n      ‫الســاعة الواحــدة والثلــث وفيهــا حضــر املدعــي العــام وجــرى تســليمه‬\n      ‫نســخة مــن قــرار املدعــى عليــه‪ ............./‬رقــم (‪ )..............‬وتاريــخ‬\n      ‫‪1434/11/25‬ه ـ لتقــدمي اعتراضــه عليــه يف الوقــت احملــدد نظام ـ ًا‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وحــرر يف ‪1434/11/25‬ه ـ ‪ .‬احلمــد هلل‬\n      ‫وحــده وبعــد ويف يــوم األحــد ‪1434/12/22‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة وأربعــن دقيقــة وقــد وردتنــا الئحــة اعتراضيــة مــن املدعــي العــام‬\n      ‫قيــدت بهــذه احملكمــة برقــم ‪ 34/22286‬يف ‪1434/12/18‬ه ـ مكونــة‬\n      ‫مــن ثــاث صفحــات ولــم أجــد فيهــا مــا يؤثــر علــى احلكم وجــرى إرفاقها‬\n      ‫باملعاملــة وقــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n      ‫اجلزائيــة املتخصصــة لتدقيــق احلكــم حســب املتبــع‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/12/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫املتخصصــة القائــم بعمــل فضيلــة القاضــي ‪ ......... .‬أثنــاء انتدابــه يف دورة‬\n      ‫تدريبيــة خــارج احملكمــة مبوجــب خطــاب التكليــف املوجــة لنــا مــن‬\n\n\n‫‪245‬‬\n\f‫قبــل رئيــس احملكمــة املســاعد برقــم ‪ 35/2976‬يف ‪1435/2/12‬هـ ويف‬\n‫يــوم الثالثــاء ‪1435/2/14‬ه ـ فتحــت اجللســة الســاعة الواحــدة والنصــف‬\n‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف اجلزائيــة املتخصصــة‬\n‫باخلطــاب ‪ 34/2104‬وتاريــخ ‪1435/2/12‬ه ـ واحملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة املتخصصــة املســاعد برقــم ‪ 35/3090‬وتاريخ‬\n‫‪1435/2/13‬هــ‪ ،‬واملتعلــق بالدعــوى العامــة ضــد‪ ،........... /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ، )............‬وقــد ُظ ّهــر القــرار‬\n‫مبــا نصــه ‪ ( :‬فقــد اطلعنــا علــى هــذا القــرار رقــم ‪ 4/34/37‬وتاريــخ‬\n‫‪1434/11/25‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ ................/‬وأصدرنــا‬\n‫القــرار رقــم ‪/1/449‬ص وتاريــخ ‪1435/2/7‬ه ـ املتضمــن املصادقــة على‬\n‫احلكــم‪ .‬واهلل املوفــق )‪ .‬لــذا جــرى إحلاقــه حتــى ال يخفــى وصلــى اهلل‬\n                               ‫علــى نبينــا محمــد ‪،‬حــرر يف ‪1435/2/14‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪246‬‬\n\f247\n\f248\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":227,"source_page_end":248,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1625a18119955153b6ae3c8601b42850057d11ab006aeb5b8256a2fc89228fa1","normalized_text_hash":"277fc0e645ec771393658670cf78f5b2a97ef8ef5ce9ef224b3b128a05151362","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p227-4-34-37"},{"id":"81714484-7278-521c-9aad-d437be3d6c34","document_type":"judgment","category":"judicial","subcategory":"general","title":"مظاهرات -مشاركة يف التجمع -إقرار -األدلة املوجبة لطاعة ولي األمر -ثبوت -سجن -جلد -تأجيل تنفيذ حكم بالسجن ملصلحة يراها القاضي -تنفيذ احلكم املوقوف تنفيذه عند العود .","document_number":"3449559","case_number":"3450649","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/27","year":"1434","subject":"مظاهرات -مشاركة يف التجمع -إقرار -األدلة املوجبة لطاعة ولي األمر -ثبوت -سجن -جلد -تأجيل تنفيذ حكم بالسجن ملصلحة يراها القاضي -تنفيذ احلكم املوقوف تنفيذه عند العود .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3449559 :‬تاريخه‪1434/2/27 :‬هـ‬\n                         ‫رقم الدعوى‪3450649 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34227466‬تاريخه‪1434/5/29 :‬هـ‬\n\n\n      ‫مظاهــرات ‪ -‬مشــاركة يف التجمــع ‪ -‬إقــرار ‪ -‬األدلــة املوجبــة لطاعــة‬\n      ‫ولــي األمــر ‪ -‬ثبــوت ‪ -‬ســجن ‪ -‬جلــد ‪ -‬تأجيــل تنفيــذ حكــم بالســجن‬\n      ‫ملصلحــة يراهــا القاضــي ‪ -‬تنفيــذ احلكــم املوقــوف تنفيــذه عنــد العــود ‪.‬‬\n\n\n\n\n      ‫‪ -‬أن الســمع والطاعــة لولــي األمــر أكــدت عليــه النصــوص الشــرعية‬\n      ‫كمــا يف قولــه تعالــى‪(( :‬يأيهــا الذيــن أمنــوا أطيعــوا اهلل وأطيعــوا‬\n      ‫الرســول وأولــي األمــر منكــم)) وقولــه عليــه الصــاة والســام (( الســمع‬\n      ‫والطاعــة علــى املــرء املســلم فيمــا أحــب وكــره مــا لــم يؤمــر مبعصيــة ))‬\n      ‫رواه البخــاري ‪ .‬ويقــول اإلمــام أحمــد بــن حنبــل رحمــه اهلل ((إنــي ألرى‬\n      ‫طاعــة أميــر املؤمنــن يف الســر والعالنيــة ويف عســري ويســري ومنشــطي‬\n      ‫ومكرهــي وأثــرة علــي وإنــي ألدعــو اهلل لــه بالتســديد والتوفيــق يف الليــل‬\n                                                                           ‫والنهــار )) ‪.‬‬\n\n\n\n\n      ‫اتهــام املدعــي العــام املذكــور باحلضــور يف التجمــع والتظاهــر الــذي دعــا‬\n      ‫لــه مثيــرو الفتنــة وتكــرار قيــام املذكــور مبثــل هــذا الفعــل ‪ ،‬ويطلــب‬\n      ‫النظــر يف مــا أســند إليــه ‪ ،‬واحلكــم عليــه بعقوبــة تعزيريــة تردعــه وتزجر‬\n      ‫غيــره والتشــديد عليــه لتكــرار ذلــك منــه ‪ .‬وباســتجواب املتهــم املذكــور‬\n‫‪249‬‬\n\f‫أفــاد بأنــه علــم عــن التجمــع عــن طريــق موقــع التواصــل االجتماعــي‬\n‫(تويتــر) حيــث كان ينــوي احلضــور للتجمــع يف أســواق ‪ .......‬وانــه قــام‬\n‫بإرســال رســالة عــن طريــق أحــد برامــج احملادثــة لزميلــه ‪ ....‬يخبــره فيهــا‬\n‫مبــكان وموعــد التجمــع فاتفقــا علــى الذهــاب واملشــاركة معهــم ‪،‬‬\n‫وبإعــادة اســتجوابه تراجــع عــن أقوالــه الســابقة وأقــر بأنــه حضــر للســوق‬\n‫للمشــاركة يف التجمــع ‪ ،‬وأفــاد أنــه ال يعــرف أحــد ًا مــن املشــاركني يف‬\n‫التجمــع غيــر زميلــه ‪ ....‬وذكــر أنــه ســبق لــه أن شــارك يف جتمــع ســابق‬\n‫يف حــي ‪ ............‬لنصــرة املعتقلــن وقبــض عليــه بتاريــخ ‪1433/9/18‬ه ـ‬\n‫وبالبحــث عــن ســوابقه تبــن انــه مت القبــض عليــه يف التجمــع الــذي‬\n‫حصــل يف حــي ‪ ............‬بتاريــخ ‪1433/9/18‬ه ـ وأحيــل إلــى احملكمــة‬\n‫اجلزئيــة وصــدر بحقــه حكــم شــرعي يقضــي بســجنه أربعــه أشــهر مــع‬\n‫وقــف التنفيــذ ‪ ،‬وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام‬\n‫للمذكــور باالشــتراك باحلضــور والتواجــد يف التجمــع والتظاهــر الــذي‬\n‫دعــا لــه مثيــرو الفتنــة وتكــرار قيــام املذكــور مبثــل هــذا الفعــل وذلــك‬\n                                                        ‫لألدلــة والقرائــن التاليــة‪:‬‬\n       ‫‪ -1‬ما ورد يف اإلقرار املنوه عنه املدون يف محضر التحقيق املرفق‪.‬‬\n      ‫‪ -2‬ما ورد يف أقواله املنوه عنها املدونة يف محضر التحقيق املرفق‪.‬‬\n‫‪ -3‬مــا ورد يف محضــر القبــض املرفــق ‪ ،‬أقــر املدعــى عليــه مبــا جــاء‬\n‫يف الدعــوى وأنــه نــادم علــى مــا فعــل ؛ وألن يف فعلــه مخالفــة صريحــة‬\n‫لتعليمــات ولــي األمــر الــذي منــع مثــل هــذه التجمعــات منعــا مشــددا‬\n‫ملصلحــة ظاهــرة ‪ ،‬وهــذا املنــع موافــق ملذهــب ومنهــج أهــل الســنة‬\n‫واجلماعــة يف نصــح الــوالة والــذي يقضــي بعــدم التشــهير بهــم يف املجامــع‬\n                                             ‫العامــة ملــا يوقــع ذلــك مــن الفتنــة‪.‬‬\n\n\n                                                                                          ‫‪250‬‬\n\f      ‫وحيــث ثبــت إدانتــه باالشــتراك يف احلضــور يف التجمــع املذكــور وقــد‬\n      ‫جــرى مناصحــة املدعــى عليــه وأبــدى اســفه وندمــه وتعهــد بعــدم العــودة‬\n          ‫ملثــل ذلــك مســتقبال ولكونــه طالبــا يف اجلامعــة واســتصالحا حلالــه ‪.‬‬\n                                                     ‫وعليه جرى احلكم مبا يلي ‪:‬‬\n      ‫‪ -1‬يعــزر بالســجن أربعــة اشــهر يحتســب منهــا مــدة توقيفــه ومبــا انــه‬\n      ‫مفــرج عنــه اآلن فيؤجــل تنفيــذ الســجن بحقــه حتــى تاريــخ ‪1434/8/1‬ه ـ‬\n      ‫بنــاء علــى املــادة (‪ )218‬مــن نظــام اإلجــراءات اجلزائيــة مراعــاة لظروفــه‬\n                                                    ‫الدراســية واســتصالح ًا حلالــه‪.‬‬\n      ‫‪ -2‬طلــب املدعــي العــام تنفيــذ احلكــم الصــادر بحقــه يف القضيــة‬\n      ‫الســابقة لكونــه موقــف التنفيــذ فــإن فضيلــة مصــدر احلكــم الســابق‬\n      ‫قــد صــرح يف حكمــه أنــه ينفــذ احلكــم املوقــوف يف حــال العــود ملثــل‬\n      ‫هــذا الفعــل فــا يحتــاج بعــد ذلــك إلــى إيضــاح أو بيــان ‪ ،‬وقــرر املدعــي‬\n                                                ‫العــام واملدعــى عليــه االعتــراض ‪.‬‬\n                              ‫وصدق احلكم من محكمة االستئناف بالرياض ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 3450649‬وتاريــخ ‪ 1434/01/28‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34251199‬وتاريــخ ‪ 1434/01/28‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/02/27‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ ...... /‬وقــدم الئحــة دعوى عامه ضد املدعى‬\n      ‫عليــه‪21 ، .......‬عامــا ســعودي ‪ ،‬بالهويــة رقــم (‪ ).....‬نصهــا كالتالــي ‪:‬‬\n\n‫‪251‬‬\n\f‫يف مســاء يــوم الثالثــاء املوافــق ‪1433/12/28‬ه ـ مت القبــض علــى املدعــو‬\n‫‪.......‬ســعودي اجلنســية (مت فــرز أوراق مســتقله بحقــه) اثــر ورود بالغــات‬\n‫مــن عــدة أشــخاص عــن قيــام مجموعــه يحملــون الفتــات داخــل ســوق‬\n‫‪ ........‬كمــا ورد يف ثنايــا احــد البالغــات ذكــرا لوصــف ســيارة املتهــم‬\n‫‪.......‬ويف وقــت الحــق مــن مســاء يــوم الســبت املوافــق ‪1434/1/3‬ه ـ مت‬\n‫القبــض علــى املتهــم املذكــور لقيامــه مبشــاركه املدعــو ‪.......‬بالتجمــع‬\n‫داخــل الســوق املذكــور ثــم تبــن انــه ســبق القبــض عليــه يف قضيــه‬\n‫مماثلــه وباســتجواب املتهــم املذكــور أفــاد بأنــه علــم عــن التجمــع عــن‬\n‫طريــق موقــع التواصــل االجتماعــي (تويتــر) حيــث كان ينــوي احلضــور‬\n‫للتجمــع يف أســواق ‪ .....‬وانــه قــام بإرســال رســالة عــن طريــق احــد برامــج‬\n‫احملادثــة لزميلــه ‪....‬يخبــره فيهــا مبــكان وموعــد التجمــع فاتفقــا علــى‬\n‫الذهــاب واملشــاركة معهــم فحضــر زميلــه إلــى منزلــه الكائــن بحــي‬\n‫‪ .....‬فعــدل عــن رأيــه ألمــر عائلــي خــاص بــه ويف يــوم الســبت املوافــق‬\n‫‪1434/1/3‬ه ـ وبعــد خروجــه مــن صــاه العشــاء قبــض عليــه رجــال‬\n‫األمــن وال يعــرف ملــاذا ‪ ،‬ذكــر زميلــه انهمــا ذهبــا ســويا للتجمــع حيــث‬\n‫أن عالقتــه‪ ...........‬عالقــة زمالــة وال توجــد بينهمــا عــداوة ومســتعد‬\n‫ملواجهتــه بذلــك ‪ .‬وبإعــادة اســتجوابه تراجــع عــن أقوالــه الســابقة وأقــر‬\n‫بأنــه حضــر للســوق للمشــاركة يف التجمــع وانــه هــو مــن اخبــر زميلــه‬\n‫‪......... /‬بالتجمــع حيــث قــام بإرســال رســالة لــه عــن طريــق احــد برامــج‬\n‫احملادثــة يخبــره فيهــا مبــكان وموعــد التجمــع فقــام ‪..........‬بالذهــاب‬\n‫إليــه مبنزلــه الكائــن بحــي العقيــق واركبــه يف ســيارته وتوجهــا إلــى‬\n‫أســواق ‪ .....‬وصليــا العشــاء يف مســجد الســوق وبعــد الصــاة انتظــرا‬\n‫قليــا ثــم حضــر عــدة أشــخاص فدخلــوا جميع ـ ًا ومعهــم املذكوريــن‬\n\n\n                                                                                    ‫‪252‬‬\n\f      ‫يف ســاحة املســجد ثــم اصطفــوا ســوي ًا وقامــوا بفتــح الالفتــات التــي‬\n      ‫كانــت معهــم وكان عددهــم حوالــي ثالثــن شــخص ًا ثــم بعــد ذلــك‬\n      ‫قامــوا باملســيرة وكانــوا يحملــون الالفتــات ومــع أحدهــم مكبــر صــوت‬\n      ‫وكانــوا يــرددون ( نفديــك بالــروح ‪ .‬نفديــك بالــدم ‪ .‬فكــوا األســير )‬\n      ‫ومــن ثــم خرجــوا مــن الســوق وهــم يهتفــون بهــذه الهتافــات وبعدهــا خرجــا‬\n      ‫وركبــا يف الســيارة وركــب معهمــا شــخص أخــر ال يعرفــه ومــن ثــم قامــا‬\n      ‫بإنزالــه خلــف أســواق ‪ .....‬وأفــاد انــه ال يعــرف احــد مــن املشــاركني يف‬\n      ‫التجمــع غيــر زميلــه‪ ......‬وأفــاد أيض ـ ًا أنــه لــم يكــن يحمــل هــو أو زميلــه‬\n      ‫أي الفتــات أو مكبــرات صــوت أو مــا شــابهها وذكــر أنــه ســبق لــه أن‬\n      ‫شــارك يف جتمــع ســابق يف حــي ‪ ............‬لنصــرة املعتقلــن وقبــض عليــه‬\n      ‫بتاريــخ ‪1433/9/18‬ه ـ وبالبحــث عــن ســوابقه تبــن أنــه مت القبــض عليه‬\n      ‫يف التجمــع الــذي حصــل يف حــي ‪ .....‬بتاريــخ ‪1433/9/18‬ه ـ وأحيــل إلــى‬\n      ‫احملكمــة اجلزائيــة وصــدر بحقــه حكــم شــرعي يقضــي بســجنه أربعــة‬\n      ‫أشــهر مــع وقــف التنفيــذ وقــد أســفرت إجــراءات التحقيــق عــن توجيــه‬\n      ‫االتهــام املذكــور باالشــتراك باحلضــور والتواجــد يف التجمــع والتظاهــر‬\n      ‫الــذي دعــا لــه مثيــري الفتنــه وتكــرار قيــام املذكــور مبثــل هــذا الفعــل‬\n                                                    ‫وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n               ‫‪ -1‬ما ورد يف إقرار املنوه عنه املدون يف محضر التحقيق املرفق‪.‬‬\n             ‫‪ -2‬ما ورد يف أقواله املنوه عنها املدونة يف محضر لتحقيق املرفق‪.‬‬\n      ‫‪ -3‬مــا ورد يف محضــر القبــض املرفــق‪ .‬وحيــث أن ما اقدم عليه املذكور‬\n      ‫فعــل محــرم شــرع ًا ومخالف ـ ًا ومعاقب ـ ًا عليــه نظامــا اطلــب النظــر يف‬\n      ‫مــا اســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تردعــه وتزجــر غيــره‬\n      ‫والتشــديد عليــه لتكــرار ذلــك منــه وتنفيــذ احلكــم الصــادر بحقــه يف‬\n\n\n‫‪253‬‬\n\f‫القضيــة الســابق كونــه موقــف التنفيــذ بشــرط عــدم العــودة مبثــل فعلــه‬\n‫هــذه دعــواي ‪ .‬وبســؤال املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره املدعــي‬\n‫العــام صحيــح فقــد علمــت بوجــود جتمــع بســوق ‪ .....‬مــن اجــل املوقوفــن‬\n‫وذلــك عــن طريــق موقــع التواصــل االجتماعــي وقمــت بإرســال رســالة‬\n‫لزميلــي ‪ .....‬وأخبرتــه بذلــك ووافــق علــى أن نذهــب ســويا للمشــاركة‬\n‫يف هــذا التجمــع وذهبنــا إلــى ســوق ‪ .....‬وبعــد أن صلينــا العشــاء يف‬\n‫مســجد الســوق حضــر عــده أشــخاص إلــى ســاحة املســجد وقامــوا بفتــح‬\n‫الفتــات كتــب عليهــا الشــعارات املذكــورة يف الئحــة الدعــوى ولــم‬\n‫أحمــل الفتــه أو مكبــر صــور أو مــا شــابهها وإمنــا قمــت بالســير معهــم‬\n‫داخــل الســوق والــذي دعانــي لذلــك هــو التعاطــف مــع املوقوفــن فقــط‬\n‫ولــم يكــن أحــد مــن أقربائــي موقوف ـ ًا واســتمرت هــذه املســيرة حوالــي‬\n‫دقيقتــن فقــط ثــم خرجنــا مــن الســوق ومــا ذكــره املدعــي العــام أننــي‬\n‫ســبق أن شــاركت يف جتمــع ســابق يف حــي ‪ ............‬صحيــح وحكــم‬\n‫علــي شــرعا بالســجن أربعــة أشــهر مــع وقــف التنفيــذ بعــد أن أمضيــت‬\n‫ثمانيــة وثالثــن يومــا ونــادم علــى مــا حصــل منــي وقــد ندمــت كثيــر ًا‬\n‫بســبب مــا حصــل لوالــدي مــن املراجعــات الكثيــرة للدوائــر املختصــة‬\n‫كاحملكمــة والســجن واالدعــاء العــام والشــرطة وأنــا طالــب جامعــي‬\n‫ال على دراســتي وطاعــة والدي‬      ‫بكليــه الشــريعة وســوف أحــرص مســتقب ً‬\n‫ال وأنــا اآلن مفــرج عنــي‬ ‫وولــي أمــري ولــن أقــوم بهــذه األعمــال مســتقب ً‬\n‫وأرجــو مراعــاة ظــرويف الدراســية هــذه إجابتــي ‪ .‬وباالطــاع علــى املعاملة‬\n‫وجــدت ضمــن املرفقــات صــورة مــن القــرار الشــرعي رقــم ‪33439587‬‬\n‫وتاريــخ ‪1433/10/28‬ه ـ الصــادر مــن فضيلــة القاضــي ‪.........‬وتضمــن‬\n‫احلكــم علــى املدعــى عليــه بالســجن اربعــة اشــهر مــن تاريــخ إيقافــه‬\n\n\n                                                                                    ‫‪254‬‬\n\f      ‫ينفــذ منهــا مــا مضــى مــن إيقــاف ويوقــف تنفيــذ باقــي املــدة علــى انــه إذا‬\n      ‫شــارك يف أي جتمــع أو اعتصــام أو مظاهــره ممــا منــع منهــا ولــي األمــر‬\n      ‫فتنفــذ عليــه املــدة الباقيــة مــن غيــر تأثيــر علــى عقوبــة اجلــرم اجلديــد ‪.‬‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه‬\n      ‫باملشــاركة يف التجمــع املذكــور وبــرر ذلــك بأنــه مــن بــاب التعاطــف مــع‬\n      ‫املوقوفــن وانــه ال يعــرف مــن املشــاركني ســوى زميلــه ‪ .......‬وقــرر انــه‬\n      ‫لــم يرفــع الفتــه وإمنــا شــارك يف املســيرة ملــدة دقيقتــن وحيــث فعلــه فيــه‬\n      ‫مخالفــة صريحــه لتعليمــات ولــي األمــر الــذي منــع مثــل هــذه التجمعــات‬\n      ‫منعــا مشــددا ملصلحــة ظاهــرة وهــذا املنــع موافــق مــع مذهــب ومنهــج أهــل‬\n      ‫الســنة واجلماعــة يف نصــح الــوالة والــذي يقضــي بعــدم التشــهير بهــم يف‬\n      ‫املجامــع العامــة ملــا يوقــع ذلــك مــن الفتنــة كمــا أن الســمع والطاعــة لولــي‬\n      ‫األمــر أكــدت عليــه النصــوص الشــرعية كمــا يف قولــه تعالــى ((يأيهــا‬\n      ‫الذيــن امنــوا أطيعــوا اهلل وأطيعــوا الرســول وأولــي األمر منكــم)) وقوله‬\n      ‫عليــه الصــاة والســام ((الســمع والطاعــة علــى املــرء املســلم فيمــا احــب‬\n      ‫وكــره مــا لــم يؤمــر مبعصيــه )) رواه البخــاري ويقــول اإلمــام احمــد بــن‬\n      ‫حنبــل رحمــه اهلل ((إنــي ألرى طاعــة أميــر املؤمنــن يف الســر والعالنيــة‬\n      ‫ويف عســري ويســري ومنشــطي ومكرهــي وأثــرة علــي وانــي الدعــوا اهلل‬\n      ‫لــه بالتســديد والتوفيــق يف الليــل والنهــار )) وحيــث مت مناصحــة املدعــى‬\n      ‫عليــه وأبــدى أســفه وندمــه وتعهــد بعــدم العــودة ملثــل ذلــك مســتقبال‬\n      ‫ولكونــه طالبــا يف اجلامعــة واســتصالحا حلالــه لــذا حكمــت عليــه مبــا‬\n      ‫يلــي ‪ :‬ثبــت لــدي إدانتــه باالشــتراك يف احلضــور والتواجــد يف التجمــع‬\n      ‫املذكــور وتكــرار ذلــك منــه ويعــزر بالســجن أربعــة أشــهر يحتســب‬\n      ‫منهــا مــده توقيفــه ومبــا أنــه مفــرج عنــه اآلن فيؤجــل تنفيــذ الســجن‬\n\n\n‫‪255‬‬\n\f‫بحقــه حتــى تاريــخ ‪1434/8/1‬ه ـ بنــاء علــى املــادة (‪ )218‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة مراعــاة لظروفــه الدراســية واســتصالحا حلالــه أمــا‬\n‫طلــب املدعــي العــام تنفيــذ احلكــم الصــادر بحقــه يف القضيــة الســابقة‬\n‫لكونــه موقــف التنفيــذ فــإن فضيلــة مصــدر احلكــم الســابق قــد صــرح‬\n‫يف حكمــه أنــه ينفــذ احلكــم املوقــوف يف حــال العــودة ملثــل هــذا الفعــل‬\n‫فــا يحتــاج بعــد ذلــك إلــى إيضــاح أو بيــان وبتــاوة احلكــم قــرر املدعــي‬\n‫العــام اعتراضــه بالئحــة وقــرر املدعــى عليــه اعتراضــه بالئحــة وجــرى‬\n‫تســليمهما نســخة احلكــم وأفهمــا مبــدة االعتــراض ثالثــن يومــا اعتبــارا‬\n‫مــن تاريخــه وعليــه حصــل التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ .‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪34251199‬‬\n‫وتاريــخ ‪1434/4/21‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ‪ ........../‬املســجل برقــم‪ 3449559‬وتاريــخ‬\n‫‪1434/2/27‬ه ـ اخلــاص بدعــوى املدعــي العــام ضد‪......../‬التهامــه‬\n‫بقضيــة مظاهــرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة والالئحــة االعتراضيــة قررنــا املصادقــة علــى احلكــم‪.‬‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪256‬‬\n\f257\n\f258\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":249,"source_page_end":258,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"24e38e5d392b918fc60c24a8de78c8fffd74df4cbd60f2f2d4a1eb3b4b54b396","normalized_text_hash":"118f03260b4b020076a3041b342168cc0f43457e347b5bce0646dc69b11213a0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p249-3449559"},{"id":"67498f65-688e-5825-9fe1-85017bd1dba6","document_type":"judgment","category":"judicial","subcategory":"general","title":"ساح -إطاق عيار ناري بقصد الترويع -صغر سن املدعى عليه - تنازل صاحب احلق اخلاص -التعزير بالسجن واجللد -التشهير .","document_number":"3431544","case_number":"3450035","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/6","year":"1434","subject":"ساح -إطاق عيار ناري بقصد الترويع -صغر سن املدعى عليه - تنازل صاحب احلق اخلاص -التعزير بالسجن واجللد -التشهير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/6 :‬هـ‬  ‫رقم الصك ‪3431544 :‬‬\n                          ‫رقم الدعوى ‪3450035:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3450988‬تاريخه‪1434/2/30 :‬هـ‬\n\n\n       ‫ســاح ‪-‬إطــاق عيــار نــاري بقصــد الترويــع ‪ -‬صغــر ســن املدعــى عليــه ‪-‬‬\n       ‫تنــازل صاحــب احلــق اخلــاص ‪ -‬التعزيــر بالســجن واجللــد‪ -‬التشــهير ‪.‬‬\n\n\n\n\n                          ‫‪-‬قول اهلل تعالى (وال تعتدوا إن اهلل ال يحب املعتدين )‬\n       ‫‪-‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬مــن أشــار إلــى أخيــه بحديــدة فــإن‬\n                   ‫املالئكــة تلعنــه حتــى يدعهــا وإن كان أخــاه ألبيــه وأمــه )‪.‬‬\n\n\n\n\n       ‫‪-‬ادعــى املدعــي العــام علــى املدعــى عليــه بقيامــه بإطــاق طلقــة ناريــة‬\n       ‫واحــدة يف الهــواء مــن مســدس لغــرض تخويــف املجنــي عليــه ويطلــب‬\n       ‫إثبــات إدانتــه وتعزيــره شــرعا ‪،‬حيــث ورد بــاغ للشــرطة مــن املدعــو‬\n       ‫‪ ...‬مفــاده قيــام ابــن أخيــه املدعــو‪ .../‬برميــه بحجــارة علــى رأســه فــرزت‬\n       ‫لــه أوراق مســتقلة وقيــام ابنــه املدعــى عليــه بإطــاق النــار يف الهــواء‬\n       ‫‪،‬وعنــد االنتقــال للموقــع برفقــة األدلــة اجلنائيــة ومبعاينــة املوقــع اتضــح‬\n       ‫وجــود آثــار بقــع دمويــة ومت ضبــط الســاح الــذي مت إطــاق النــار منــه‬\n       ‫والتحفــظ عليــه ‪،‬وأقــر املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع بــأن‬\n       ‫املجنــي عليــه ضــرب والــده فــأراد تخويفــه ‪،‬وبنــاء علــى مــا تقــدم ولصغــر‬\n\n‫‪259‬‬\n\f‫ســن املدعــى عليــه وتنــازل صاحــب احلــق اخلــاص األمــر الــذي يســتوجب‬\n‫تخفيــف العقوبــة عنــه ‪،‬فقــد حكمــت احملكمــة بــأن يعــزر املدعــى‬\n‫عليــه بالســجن مــدة شــهرين مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‬\n‫‪،‬وجلــده مائــة جلــده مفرقــة علــى دفعتــن كل دفعــة خمســون جلــده‬\n‫بــن الدفعتــن مــدة ال تقــل عــن عشــرة أيــام علــى أن يكــون اجللــد يف‬\n‫مــكان عــام ‪،‬وقــرر املدعــي العــام االعتــراض وطلــب االســتئناف بــدون‬\n‫‪،‬وصــدق احلكــم مــن محكمــة‬    ‫الئحــة ‪،‬وقــرر املدعــى عليــه القناعــة ُ‬\n                                                                ‫االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي باحملكمــة العامــة بأبــو‬\n‫عريش وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة العامة‬\n‫بأبــي عريــش برقــم ‪ 3450035‬وتاريــخ ‪1434/01/28‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 34233617‬وتاريــخ ‪ 1434/01/27‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة التاســعة وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واإلدعــاء‬\n‫العــام ‪..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.........‬‬\n‫واملفــوض باخلطــاب رقــم هــ‪7‬ج‪ 513/‬وتاريــخ ‪1428/7/9‬ه ـ وأدعــى قائــا‬\n‫بصفتــي مدعيــا عامــا بدائــرة التحقيــق واإلدعــاء العــام مبحافظــة أبــو‬\n‫عريــش أدعــي علــى‪ 19 .........‬عامــا ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬أوقــف بتاريــخ ‪1433/11/27‬ه ـ لكــون جرميتــه مــن‬\n‫اجلرائــم املوجبــة للتوقيــف اســتنادا للقــرار الــوزاري رقــم ‪ 1900‬وتاريــخ‬\n‫‪1428/7/9‬ه ـ وأودع بقســم ســجن أبــو عريــش موجــب أمــر التمديــد‬\n‫والتوقيــف رقــم ‪/2406/19/23‬م ك وتاريــخ ‪1433/12/3‬ه ـ إنــه يف متــام‬\n\n                                                                                       ‫‪260‬‬\n\f      ‫الســاعة اخلامســة مســاء يــوم الســبت املوافــق ‪1433/11/27‬ه ـ ورد بــاغ‬\n      ‫لشــرطة منــي مالــك مــن املدعــو ‪ .......‬مفــاده قيــام ابــن أخيــه املدعــو‪........‬‬\n      ‫برميــه بحجــارة علــى رأســه فــرزت لــه أوراق مســتقلة وقيــام ابنــه املدعــى‬\n      ‫عليــه بإطــاق النــار يف الهــواء وفــور تلقــي البــاغ جــرى االنتقــال للموقــع‬\n      ‫برفقــة األدلــة اجلنائيــة واتضــح أن موقــع احلادثــة ‪ ......‬ويبعــد عــن مركــز‬\n      ‫شــرطة بنــي مالــك حوالــي عشــرين كيلومتــر تقريبــا ومبعاينــة املوقــع‬\n      ‫وجــد آثــار بقــع دمويــة ومت ضبــط الســاح الــذي مت إطــاق النــار منــه‬\n      ‫والتحفــظ عليــه وهــو ســاح مرخــص وقــد جــرت معاينــة املوقــع مــن قبــل‬\n      ‫املختصــن باألدلــة اجلنائيــة ومت البحــث عــن األظرفــة الفارغــة ولــم يتــم‬\n      ‫العثــور عليهــا وقــد صــدر التقريــر الفنــي رقــم ‪/649‬أســلحة‪1433/‬هـ أنــه‬\n      ‫بفحــص املســدس عيــار ‪25?7.62‬ملــم يحمــل الرقــم ‪ 07116PK‬مــع املخــزن‬\n      ‫تبني أن املســدس يعمل بحالة جيدة وباســتجواب املدعى عليه ومواجهته‬\n      ‫بالتهمــة املنســوبة إليــه أفــاد أنــه يف يــوم الســبت املوافــق ‪1433/11/27‬ه ـ‬\n      ‫حصلــت مضاربــة بــن والــده ‪ .......‬واملدعــو‪ ......‬وقــام املدعــو برمــي حجــر‬\n      ‫علــى رأس والــده وقــد كان أي املدعــى عليــه حاضــر يف املوقــع املســمى‬\n      ‫‪ ...‬وعندمــا شــاهد الــدم ينــزف مــن والــده اجتــه إلــى منــزل والــده وأخــذ‬\n      ‫املســدس مــن الــدوالب وقــام بتعميــد املســدس وعبــأه طلقــات ومــن ثــم‬\n      ‫اجتــه إلــى موقــع املضاربــة وأطلــق النــار مــن املســدس العائــد لوالــده‬\n      ‫طلقــة واحــدة فقــط مــن فــوق رأس املدعــو ‪ ....‬لتخويفــه وبعدهــا هــرب إلى‬\n      ‫منزلــه كونــه قريــب وبعــد ذلــك أســعف والــده واملســدس نــوع ‪07116PK‬‬\n      ‫صناعــة بولنديــة مرخــص مبوجــب الترخيــص رقــم ‪ 1024713164‬وأن‬\n      ‫والــده لــم يقــم بتحريضــه علــى إطــاق النــار علــى املدعــو ‪ ....‬ولــم يعلــم‬\n      ‫والــده بأنــه أخــذ املســدس العائــد لــه واختتــم أقوالــه باملصادقــة عليهــا‬\n\n\n‫‪261‬‬\n\f‫وقــد أســفر التحقيــق عــن توجيــه االتهــام إليــه بقيامــه بإطــاق طلقــة‬\n‫ناريــة واحــدة يف الهــواء مــن مســدس عيــار ‪25?7.62‬ملــم لغــرض تخويــف‬\n‫املدعــو ‪ .......‬وذلــك لألدلــة والقرائــن التاليــة ‪1‬ـ مــا جــاء يف إقــراره حتقيقــا‬\n‫املنــوه عنــه واملصــدق عليــه شــرعا واملــدون صفحــة ‪ 9‬لفــة رقــم ‪2 1‬ـ مــا جــاء‬\n‫يف محضــر االنتقــال واملعاينــة املنــوه عنــه واملرفــق لفــة رقــم ‪3 9‬ـ مــا جــاء‬\n‫يف التقريــر الفنــي للســاح املســتخدم الصــادر مــن إدارة األدلــة اجلنائيــة‬\n           ‫بجــازان رقــم ‪/649‬أســلحة‪1433/‬هـ املرفــق بــاألوراق لفــة رقــم ‪29‬‬\n‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه‬\n‫وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا‬\n‫أقــدم عليــه علمــا بــأن احلــق اخلــاص انتهــى بالتنــازل واهلل املوفــق وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه بعــد التأكــد مــن هويتــه وأهليته‬\n‫املعتبــرة شــرعا أجــاب قائــا مــا ذكــره املدعــي العــام مــن قيامــي بإطالق‬\n‫طلقــة ناريــة واحــدة يف الهــواء مــن مســدس عيــار ‪25?7.62‬ملــم لغــرض‬\n‫تخويــف املدعــو ‪ ......‬فصحيــح وذلــك بعــد أن قــام بضــرب والــدي وأنــا‬\n‫أشــاهد هكــذا أجــاب عقــب ذلــك جــرى االطــاع علــى كــرت ســوابق‬\n‫املدعــى عليــه املرفــق لفــة رقــم ‪ 25‬فوجــدت أنــه خالــي مــن الســوابق كمــا‬\n‫جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املرفــق لفــة رقــم ‪8‬‬\n‫فوجــدت أنــه أوقــف بتاريــخ ‪1433/11/27‬ه ـ فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ومبــا أن املدعــي العــام يتهــم املدعــى عليــه بإطــاق‬\n‫طلقــة ناريــة واحــدة يف الهــواء مــن مســدس لغــرض تخويــف املدعــو ‪......‬‬\n‫ومبــا أن املدعــى عليــه صــادق علــى دعــوى املدعــي العــام ولصغــر ســن‬\n‫املدعــى عليــه وتنــازل صاحــب احلــق اخلــاص األمــر الــذي يتوجــه تخفيــف‬\n\n\n                                                                                           ‫‪262‬‬\n\f      ‫العقوبــة عنــه ومبــا أن مــا أقــدم عليــه املدعــي عليــه فعــل محــرم شــرعا‬\n      ‫لعمــوم قولــه تعالــى (وال تعتــدوا إن اهلل ال يحــب املعتديــن) وقــال النبــي‬\n      ‫صلــى اهلل عليــه وســلم‪ ( :‬مــن أشــار إلــى أخيــه بحديــده فــإن املالئكــة‬\n      ‫تلعنــه حتــى يدعهــا وإن كان أخــاه ألبيــه وأمــه) لذلــك كلــه وألجــل احلــق‬\n      ‫العــام فقــد قــررت مــا يلــي أوال ثبــت لــدي إدانــة املدعــى عليــه بإطــاق‬\n      ‫طلقــة ناريــة واحــدة يف الهــواء مــن مســدس لغــرض تخويــف املدعــو‬\n      ‫‪ .....‬ثانيــا يعــزر املدعــى عليــه بالســجن مــدة شــهرين مــن تاريــخ إيقافــه‬\n      ‫علــى ذمــة هــذه القضيــة ثالثــا جلــد املدعــى عليــه مائــة جلــده مفرقــة‬\n      ‫علــى دفعتــن كل دفعــة خمســون جلــده بــن الدفعتــن مــدة ال تقــل‬\n      ‫عــن عشــرة أيــام علــى أن يكــون اجللــد يف مــكان عــام وبــه حكمــت‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة بــه وقــرر املدعــي العــام‬\n      ‫االعتــراض علــى احلكــم بــدون الئحــة اعتراضيــة عليــه أمــرت برفــع‬\n      ‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وحتــى ال‬\n      ‫يخفــى جــرى تدوينــه وبــاهلل التوفيــق وأقفلــت اجللســة يف متــام الســاعة‬\n      ‫التاســعة والنصــف وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                         ‫وســلم ‪ .‬حــرر يف ‪1434/2/6‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بأبــي عريــش برقــم‬\n      ‫‪ 34233617‬وتاريــخ ‪1434/2/10‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ‪ ...... /‬برقــم ‪ 3431564‬وتاريــخ ‪1434/2/6‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪ ....... /‬يف قضيــة (إطــاق نــار) علــى‬\n      ‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n\n\n‫‪263‬‬\n\f‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n‫املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                             ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪264‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":259,"source_page_end":264,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5a391d89fcf4d6a3b5052f8a68325642ca7c6d2c5125c27be71a71b748b5a3e2","normalized_text_hash":"4f3470de67af0357bb88f116cd5d09f3bb9ca212101af29d375aa571b67d412f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p259-3431544"},{"id":"d87076cd-31ca-5874-91f8-200033df9de7","document_type":"judgment","category":"judicial","subcategory":"general","title":"ساح – إطاق عيار نار بقصد الترويع – إنكار الدعوى – قرائن مؤيدة لصحة الدعوى – تعزير للتهمة -تعزير بالسجن واجللد","document_number":"3434798","case_number":"3455189","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/11","year":"1434","subject":"ساح – إطاق عيار نار بقصد الترويع – إنكار الدعوى – قرائن مؤيدة لصحة الدعوى – تعزير للتهمة -تعزير بالسجن واجللد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/02/11 :‬هـ‬   ‫رقم الصك ‪3434798 :‬‬\n                            ‫رقم الدعوى ‪3455189:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34165495‬تاريخه‪1434/3/18 :‬هـ‬\n\n\n\n      ‫ســاح – إطــاق عيــار نــار بقصــد الترويــع – إنــكار الدعــوى – قرائــن‬\n      ‫مؤيــدة لصحــة الدعــوى – تعزيــر للتهمــة ‪ -‬تعزيــر بالســجن واجللــد‬\n                                                                    ‫والتشــهير ‪.‬‬\n\n\n\n\n      ‫‪-‬ألنــه مــن املقــرر فقهـ ًا أن التعزيــر ال يســقط بالشــبهة قال جالل الدين‬\n      ‫التعزير \" ويقول ابن جنيم‬\n                          ‫َ‬        ‫الســيوطي رحمه اهلل ‪ \" :‬الشــبه ُة ال تســقط‬\n      ‫رحمــه اهلل ‪ \" :‬التعزيـ ُـر يثبـ ُـت مــع الشــبه ِة ‪ ( ).‬األشــباه والنظائــر ‪ ,‬ص‬\n                                                                                   ‫‪) 162‬‬\n\n\n\n\n      ‫‪-‬ادعــى املدعــي العــام علــى املدعــى عليــه بقيامــه بإطــاق النــار يف الهــواء‬\n      ‫بقصــد التفريــق أثنــاء حصــول مشــاجرة‪ ،‬يطلــب إثبــات إدانتــه مبــا أســند‬\n      ‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ‪،‬حيــث إنــه ورد‬\n      ‫بــاغ للدويــات األمنيــة بــأن هنــاك ســوء تفاهــم يف حــي ‪ ....‬وعنــد االجتــاه‬\n      ‫للموقــع وجــد املبلــغ ‪...../‬مفيــد ًا بأنــه حصــل بــن ابنــه ‪ ....‬واملدعــى عليــه‬\n      ‫وأخيــه ‪ ...‬اللــذان كانــا يســتقالن ســيارة ســوء تفاهم ‪،‬حيــث قام املدعى‬\n      ‫عليــه بإطــاق النــار مــن مســدس كان يحملــه يف الهــواء ثــم فــر هارب ـ ًا‬\n      ‫مــن املوقــع وقــد مت العثــور علــى عــدد اثنــن مــن فــوارغ االعيــرة الناريــة‬\n‫‪265‬‬\n\f‫‪،‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أنكــر املدعــى عليــه‬\n‫مــا جــاء يف الدعــوى – بنــاء علــى القرائــن املؤيــدة لصحــة الدعــوى ومنهــا‬\n‫تناقــض أقــوال املدعــى عليــه وكذبــه وانطبــاق األظــرف الفارغــة يف‬\n‫موقــع املضاربــة مــع الســاح املرخــص للمدعــى عليــه فقد توجهــت التهمة‬\n‫للمدعــى عليــه – وبنــاء علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى‬\n      ‫عليــه بالســجن واجللــد – صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 3455189‬وتاريــخ ‪ 1434/02/03‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34274851‬وتاريــخ ‪ 1434/02/03‬ه ـ ففــي يــوم اإلثنــن‬\n‫املوافــق ‪ 1434/02/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬بشــأن‬\n‫دعــوى املدعــي العــام ‪ ......‬واملكلــف مبهمــة اإلشــراف علــى مكتــب‬\n‫االدعــاء العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس فــرع هيئــة‬\n‫التحقيــق واالدعــاء العــام مبنطقــة جنــران رقــم ه ـ ن ‪ 11178/2/1‬وتاريــخ‬\n‫‪1430/12/29‬ه ـ ضــد‪ ....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n‫ا يف دعــواه عليــه إنــه بتاريــخ ‪1431/1/8‬ه ـ ورد مبحضــر‬               ‫(‪ ).....‬قائ ـ ً‬\n‫الدوريــات األمنيــة رقــم ‪ ....‬يف ‪1431/1/8‬ه ـ أنــه مت تلقيهــم بالغ ـ ًا مــن‬\n‫العمليــات بــأن هنــاك ســوء تفاهــم يف حــي ‪ .........‬وعنــد اإلجتــاه للموقــع‬\n‫وجــد املبلــغ ‪ ...../‬مفيــد ًا بأنــه حصــل بــن ابنــه ‪ ...‬ســوء تفاهــم مــع املدعــى‬\n‫عليــه وأخيــه ‪ ...‬اللــذان كانــا يســتقالن ســيارة لوحــة رقــم (‪ ).... ...‬حيــث‬\n‫قــام املدعــى عليــه بتاريخــه بإطــاق النــار مــن مســدس كان يحملــه يف‬\n\n                                                                                           ‫‪266‬‬\n\f      ‫الهــواء ثــم فــر هارب ـ ًا مــن املوقــع وقــد مت العثــور علــى عــدد اثنــن مــن‬\n      ‫فــوارغ املســدس حيــث أحضرهــا املبلــغ يف كأس هــذا وقــد ســلم املوقــع‬\n      ‫واألشــخاص والفــوارغ علــى منــدوب شــرطة رجــاء إلكمــال الــازم ‪.‬‬\n      ‫وأثبت التقرير املعد من قبل إدارة األدلة اجلنائية رقم ‪/3‬أســلحة‪1431/‬هـ‬\n      ‫الصــادر لنــا بخطــاب ســعادة مديــر مركــز شــرطة رجــاء رقــم ‪ 339‬يف‬\n      ‫‪1431/1/27‬ه ـ املتضمــن أنــه مت فحــص ظرفــن فارغــن عيــار (‪7,65‬‬\n      ‫ملــم) فكانــت النتيجــة أنهــا ملســدس عيــار (‪ 7,65‬ملــم) وتطلــق عــادة مــن‬\n      ‫األســلحة الناريــة ذات العيــار نفســه (مســدس نصــف) ومطلقــه من ســاح‬\n      ‫نــاري واحــد وباالطــاع علــى ترخيــص الســاح الصــادر مــن مقــام إمــارة‬\n      ‫منطقــة جنــران املنــوه عنــه رقــم (‪ )13/23223‬اتضــح أنــه نــوع مســدس‬\n      ‫عيــار (‪ 7,65‬ملــم) يحمــل الرقــم (‪ )1238641‬ماركــة أســباني الصنــع وال‬\n                                                    ‫يــزال الترخيــص ســاري املفعــول ‪.‬‬\n      ‫وباالطــاع علــى خطــاب ســعادة مديــر شــعبة األســلحة واملتفجــرات رقــم‬\n      ‫‪ 5/135/25/3‬يف ‪1431/1/20‬ه ـ املتضمــن أن املدعــى عليــه يوجــد لديــه‬\n                                             ‫ســاح باملواصفــات املنــوه عنهــا أعــاه ‪.‬‬\n      ‫وبســماع األقــوال األوليــة للمدعــى عليــه أنكــر قيامــه بإطــاق النــار يف‬\n      ‫الهــواء بســبب اخلــاف الــذي دار بينــه وبــن أخيــه وبــن ‪ ......‬وأنكــر‬\n      ‫وجــود أي أســلحة معــه وأنــه ال يوجــد بينــه وبــن املبلــغ أي مشــاكل‬\n      ‫ســابقة وأفــاد بأنــه لــم يحصــل أي مشــكلة أساس ـ ًا ‪ .‬وباســتجوابه أفــاد‬\n      ‫مبثــل مــا أفــاد بــه يف أقوالــه األوليــة وأضــاف أنــه تشــاجر هــو وأخيــه ‪...‬‬\n      ‫مــع ‪ .....‬مشــاجر َة بســيطة باأليــادي وحضــر كبــار الســن وفكــوا بينهــم‬\n      ‫وأنــه ســمع صــوت إطــاق النــار ولكــن لــم يعلــم مــن قــام باإلطــاق ولــم‬\n      ‫يــرى مــع احلاضريــن أي ســاح وأنــه ليــس بــه أي إصابــات وال يعلــم عــن‬\n\n\n‫‪267‬‬\n\f                           ‫األظــرف الفارغــة املضبوطــة باملوقــع أي شــيء ‪..‬‬\n‫لــذا فقــد انتهــى التحقيــق إلــى توجيــه االتهــام علــى املدعــى عليــه ‪...... /‬‬\n        ‫بإطــاق النــار يف الهــواء بقصــد التفريــق أثنــاء حصــول مضاربــه ‪.‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى ســابقة واحــدة توســط‬\n‫يف بيــع وشــراء مخــدرات ‪,‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪...... /‬‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n                                                            ‫تزجــره وتــردع غيــره ‪.‬‬\n‫( علمـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل ) وبــاهلل التوفيــق هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه مــا ذكــره املدعــي العــام يف دعــواه‬\n‫ا هكــذا أجــاب ثــم جــرى منــي ســؤال‬         ‫غيــر صحيــح جمل ـ ًة وتفصي ـ ً‬\n‫املدعــي العــام هــل لديــك بينــة علــى مــا جــاء يف دعــواك فقــال ال يوجــد‬\n‫لــدي بينــة ســوى مــا جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق‬\n‫واالطــاع علــى أقــوال املدعــى عليــه األوليــة املدونــة علــى ص‪ 7-6‬مــن‬\n‫امللــف املرفــق علــى لفــة رقــم (‪ )1‬وعلــى أقوالــه حتقيق ـ ًا املدونــة علــى‬\n‫ص‪ 3-2‬مــن امللــف املرفــق علــى لفــة رقــم (‪ )27‬كمــا جــرى منــي االطــاع‬\n‫علــى محضــر االنتقــال واملعاينــة املــدون علــى ص‪ 4‬مــن امللــف املرفــق علــى‬\n‫لفــة رقــم (‪ )1‬وعلــى ترخيــص الســاح الصــادر مــن مقــام إمــارة منطقــة‬\n‫جنــران رقــم ‪ 13/23223‬واملرفــق علــى لفــة رقــم (‪ )65‬وعلــى التقريــر‬\n‫املعــد مــن إدارة األدلــة اجلنائيــة رقــم ‪/3‬أســلحة‪1431/‬هـ كمــا جــرى منــي‬\n‫االطــاع علــى أقــوال أخ املدعــى عليــه ‪ ...‬حتقيق ـ ًا املدونــة علــى ص‪ 6‬مــن‬\n                                              ‫امللــف املرفــق علــى لفــة رقــم (‪)27‬‬\n‫فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وحيــث إن املدعــى عليــه‬\n\n\n                                                                                        ‫‪268‬‬\n\f      ‫قــد أنكــر قيامــه بإطــاق النــار يف الهــواء بقصــد التفريــق أثنــاء وقــوع‬\n      ‫مضاربــة بينــه و بــن املدعــي ‪ .....‬ولــم يعتــرف بذلــك حتقيق ـ ًا ولتوجــه‬\n      ‫التهمــة القويــة عليــه يف ذلــك املؤيــدة بالقرائــن اآلتيــة ‪ -1 :‬تناقــض‬\n      ‫أقوالــه حــول وقــوع مضاربــة بينــه وبــن املدعــي حيــث إنــه أنكــر يف‬\n      ‫أقوالــه األوليــة وقــوع مضاربــة بينهمــا واعتــرف بأقوالــه حتقيقـ ًا بحصــول‬\n      ‫مضاربــة بســيطة بينهمــا باأليــدي ‪ -2‬ثبــوت كــذب املدعــى عليــه بأنــه‬\n      ‫ليــس لديــه أي ســاح نــاري مرخــص ‪ -3‬مطابقــة األظــرف الفارغــة التــي‬\n      ‫مت العثــور عليهــا يف موقــع املضاربــة للســاح النــاري املرخــص للمدعــى‬\n      ‫عليــه ‪ -4‬اعتــراف شــقيق املدعــى عليــه ‪ ....‬بســماعه إطــاق النــار أثنــاء‬\n      ‫حصــول املضاربــة وملــا كان مــن املقــرر فقه ـ ًا أن التعزيــر ال يســقط‬\n      ‫بالشــبهة قــال جــال الديــن الســيوطي رحمــه اهلل ‪ \" :‬الشــبهة ال تســقط‬\n      ‫التعزيــر \" ( األشــباه والنظائــر ‪ ,‬ص ‪ ) 162‬ويقــول ابــن جنيــب رحمــه اهلل ‪:‬‬\n      ‫\" التعزيــر يثبــت مــع الشــبهة ولــذا قالــوا يثبــت مبــا يثبــت بــه املــال ويجــري‬\n      ‫فيــه احللــف ويقضــى فيــه بالنكــول \" ( األشــباه والنظائــر ‪ ,‬ص ‪) 157‬‬\n      ‫وتأسيس ـ ًا علــى جميــع مــا ســبق فقــد قــررت مــا يأتــي أوال‪ :‬لــم يثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ثانيـاً‪ :‬تعزيــره‬\n      ‫وذلــك بســجنه ملــدة أربعــة أشــهر تبــدأ اعتبــار ًا مــن تاريــخ إدخالــه الســجن‬\n      ‫وجلــده ثمانــن جلــدة علن ـ ًا مفرقــة علــى مرتــن بــن كل مــرة وأخــرى‬\n      ‫مــدة ال تقــل عــن أســبوعني لقــاء توجــه التهمــة القويــة عليــه مبــا نســب‬\n      ‫إليــه هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫قنــع بــه كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                ‫وســلم ‪ .‬حــرر يف ‪ 1434/02/04‬ه ـ الســاعة ‪09:30‬‬\n\n\n‫‪269‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران رقــم ‪34274851‬‬\n‫وتاريــخ ‪1434/2/11‬ه ـ املرفــق بهــا القــرار الشــرعي الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ‪ .... /‬رقــم ‪ 3434798‬وتاريــخ ‪1434/2/11‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد‪ ( .... /‬ســعودي اجلنســية ) يف قضيــة (‬\n‫اطــاق نــار ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                             ‫نبينــا محمــد وآلــه وصحبــه وســلم‬\n\n\n\n\n                                                                                     ‫‪270‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":265,"source_page_end":270,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7bac75c13ee6ef84c635ff0faecc9ab2b91edff1d9941b9937ea1036be031d02","normalized_text_hash":"9e999ba8e76402bae904993548871f38854730e4dc34d95ea22cfdac4aab105a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p265-3434798"},{"id":"18825e36-0f2a-5d01-b4ba-f7281dd56028","document_type":"judgment","category":"judicial","subcategory":"general","title":"ساح –حيازة ساح بدون ترخيص -عدم تطبيق نظام األسلحة والذخائر على األحداث-ثبوت االدعاء – التعزير باجللد ومبصادرة","document_number":"34183270","case_number":"34143855","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/9","year":"1434","subject":"ساح –حيازة ساح بدون ترخيص -عدم تطبيق نظام األسلحة والذخائر على األحداث-ثبوت االدعاء – التعزير باجللد ومبصادرة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/4/9 :‬هـ‬   ‫رقم الصك ‪34183270 :‬‬\n                             ‫رقم الدعوى‪34143855:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 34308682‬تاريخه‪1434/8/29 :‬هـ‬\n\n\n\n      ‫ســاح –حيــازة ســاح بــدون ترخيــص ‪-‬عــدم تطبيــق نظــام األســلحة‬\n      ‫والذخائــر علــى األحداث‪-‬ثبــوت االدعــاء – التعزيــر باجللــد ومبصــادرة‬\n                                                                       ‫الســاح‪.‬‬\n\n\n\n\n      ‫‪ -‬تعميــم وزيــر الداخليــة رقــم ‪ 13074/16‬يف ‪1422/2/15‬ه ـ املبنــي علــى‬\n      ‫مــا صــدر مــن وزارة العــدل برقــم ‪ 310‬يف ‪1394/4/7‬ه ـ مــن أنــه ال يجــوز‬\n                                               ‫معاقبــة األحــداث بــأي نظــام ‪.‬‬\n\n\n\n\n      ‫‪ -‬ادعــى املدعــي العــام علــى املدعــى عليــه بقيامــه بحيــازة ســاح نــاري‬\n      ‫فــردي دون ترخيــص املجــرم باملــادة (‪ )4‬مــن نظــام األســلحة والذخائــر‬\n      ‫وطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫لقــاء حيــازة الســاح دون ترخيــص اســتناد ًا لبرقيــة صاحــب الســمو‬\n      ‫امللكــي نائــب وزيــر الداخليــة رقــم (‪ )32766‬وتاريــخ ‪1430/3/17‬ه ـ‬\n      ‫ومصــادرة الســاح املوصــوف اســتناد ًا للمــادة رقــم (‪ )50‬مــن نظــام‬\n      ‫ـاء علــى إخباريــة‬‫األســلحة والذخائــر ‪ -‬مت القبــض علــى املدعــى عليــه بنـ ً‬\n      ‫مفادهــا مشــاهدة املدعــى عليــه يقــود ســيارته ويحمــل ســاح ًا ناري ـ ًا –‬\n      ‫إقــرار املدعــى عليــه بالدعــوى ‪ -‬ثبتــت إدانــة املدعــى عليــه وحيــث أن‬\n\n‫‪277‬‬\n\f‫املدعــى عليــه حــدث فلــم يتــم تطبيــق نظــام األســلحة والذخائــر بحقــه‬\n‫وحكمــت احملكمــة بجلــده أربعــن جلــدة دفعــة واحــدة ومبصــادرة‬\n‫الســاح املوصــوف يف الدعــوى تعزيــر ًا ‪ -‬وقــرر املدعــي العــام االعتــراض‬\n‫وصــدق‬‫وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى عليــه القناعــة ‪ُ -‬‬\n                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باخلــرج ‪ /‬املكلــف برقــم ‪ 34143855‬وتاريــخ‬\n‫‪1434/03/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34764563‬وتاريــخ‬\n‫‪1434/03/28‬ه ـ ويف يــوم الثالثــاء املوافق‪1434/04/09‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واإلدعــاء‬\n‫العــام ‪ .....‬وادعــى علــى احلاضــر معــه ‪ /‬احلــدث ‪ ..... /‬البالــغ مــن العمــر‬\n‫ا يف دعــواه‬ ‫(‪ )15‬عام ـ ًا ســعودي اجلنســية مبوجــب الهويــة رقــم (‪ )....‬قائ ـ ً‬\n‫‪ :‬أنــه بتاريــخ ‪1434/1/5‬ه ـ ورد لشــرطة محافظــة اخلــرج مخفــر شــرطة‬\n‫اخلالديــة تقريــر دوريــات األمــن ورود بــاغ مــن أحــد املواطنــن عــن وجــود‬\n‫شــخص يقــود ســيارة نــوع ‪ ................‬رقــم لوحتهــا (‪ ).... ...‬يحمــل ســاح ًا‬\n‫ناريـ ًا وعنــد وصــول الفرقــة للموقــع قــام صاحــب الســيارة بالهــرب فتمــت‬\n‫مالحقتــه والقبــض عليــه وتبــن أنــه املدعــى عليــه ويرافقــه شــخصان‬\n‫ووجــد بالســيارة ســاح رشــاش يحمــل الرقــم (‪ )19272RN‬وورد بالتقريــر‬\n‫الفنــي رقــم (‪/68‬أســلحة‪ )1434/‬الصــادر مــن اإلدارة العامــة لألدلــة‬\n‫اجلنائيــة أن الســاح نــوع بندقيــة (‪ )....‬بولنديــة الصنــع عيــار (‪ )7062‬ملــم‬\n\n                                                                                        ‫‪278‬‬\n\f      ‫وتعمــل بحالــة جيــدة وليــس لــه عالقــة بالقضايــا املقيــدة املوجــودة أدلتهــا‬\n      ‫لديهــم وورد بخطــاب مديــر إدارة األســلحة واملتفجــرات رقــم (‪)1776‬‬\n      ‫وتاريــخ ‪1434/3/18‬ه ـ بــأن الســاح غيــر مســجل بالنظــام وبســماع أقــوال‬\n      ‫املرافقــن وهمــا ‪ ..... /‬و ‪ .....‬أفــادا بــأن الســاح عائــد للمدعــى عليــه‬\n      ‫وباســتجوابه أقــر بــأن الســاح عائــد لــه وانتهــى التحقيــق إلــى اتهامــه‬\n      ‫بحيــازة ســاح نــاري فــردي دون ترخيــص املجــرم باملــادة (‪ )4‬مــن نظــام‬\n      ‫األســلحة والذخائــر وذلــك لألدلــة والقرائــن التاليــة ‪-1:‬إقــراره املشــار‬\n      ‫إليــه املــدون علــى اللفــة رقــم (‪ )1‬ص (‪-2)10‬محضــر القبــض املشــار إليــه‬\n      ‫املــدون علــى اللفــة رقــم (‪-3)3‬أقــوال مرافقيــه املشــار إليهــا املدونــة علــى‬\n      ‫اللفــة رقــم (‪ )1‬ص (‪-4)13-12‬التقريــر الفنــي املشــار إليــه املــدون علــى‬\n      ‫اللفــة رقــم (‪-5)15‬خطــاب مديــر إدارة األســلحة واملتفجــرات املشــار إليــه‬\n                                                      ‫واملــدون علــى اللفــة رقــم ( ‪) 22‬‬\n      ‫وبالبحــث عــن ســوابقه مــن واقــع ســجله بــدار املالحظــة االجتماعيــة‬\n                 ‫بالريــاض وجــدت لــه ســابقتني األولــى مضاربــة واألخــرى لــواط ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليته املعتبرة‬\n      ‫شــرع ًا ? فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات إدانتــه‬\n      ‫مبــا أســند إليــه واحلكــم عليــه مبــا يلــي ‪-1-:‬بعقوبــة تعزيريــة لقــاء حيــازة‬\n      ‫الســاح دون ترخيــص اســتناد ًا لبرقيــة صاحــب الســمو امللكــي نائــب‬\n      ‫وزيــر الداخليــة رقــم (‪ )32766‬وتاريــخ ‪1430/3/17‬ه ـ ‪-2‬مصــادرة الســاح‬\n      ‫املوصــوف اســتناد ًا للمــادة رقــم (‪ )50‬مــن نظــام األســلحة والذخائــر هــذه‬\n      ‫دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام‬\n      ‫مــن حيازتــي ســاح نــاري ( رشــاش ) بــدون ترخيــص فصحيــح جملــة‬\n      ‫ا وقــد حزتــه بــدون ذخيــرة هكــذا أجــاب فبنــاء علــى مــا تقــدم‬     ‫وتفصيـ ً‬\n\n\n‫‪279‬‬\n\f‫ذكــره مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه قــد أقــر بحيازتــه‬\n‫الســاح املوصــوف يف الدعــوى ومبــا أن املدعــى عليــه ال زال حدثـ ًا وبنــاء‬\n‫علــى تعميــم وزيــر الداخليــة رقــم ‪ 13074/16‬يف ‪1422/2/15‬ه ـ املبنــي‬\n‫علــى مــا صــدر مــن وزارة العــدل برقــم ‪ 310‬يف ‪1394/4/7‬ه ـ مــن أنــه ال‬\n‫يجــوز معاقبــة األحــداث بــأي نظــام ‪ ..‬إلــخ ومبــا أن املدعــى عليــه صغيــر‬\n‫يف الســن عمــر ًا ومظهــر ًا لــكل مــا ســبق فقــد ثبــت لــدي إدانــة املدعــى‬\n‫عليــه مبــا أســند إليــه يف دعــوى املدعــي العــام ثــم جــرى مناصحــة احلــدث‬\n‫وتبيــن خطــورة حمــل الســاح وحكمــت بتعزيــره باجللــد أربعــن جلــدة‬\n‫دفعــة واحــدة كمــا حكمــت مبصــادرة الســاح املوصــوف يف الدعــوى‬\n‫تعزيــر ًا وبعــرض احلكــم علــى الطرفــن قنــع املدعــى عليــه وقــرر املدعــي‬\n‫العــام اعتراضــه علــى احلكــم وطلــب رفــع املعاملــة حملكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة فأجيــب لطلبــه ختمــت يف الســاعة التاســعة‬\n‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                     ‫‪1434/4/9‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج برقــم ‪341034523‬‬\n‫وتاريــخ ‪1434/8/15‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ ...... /‬املســجل برقــم ‪ 34183270‬وتاريــخ ‪1434/4/9‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ......‬يف قضيــة حمــل ســاح بــدون‬\n‫ترخيــص علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون و مفصــل بــه عليــه لــم يظهــر لألكثريــة مــا يوجــب نقــض احلكــم‬\n‫بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                               ‫الــه وصحبــه وســلم‪.‬‬\n                                                                                       ‫‪280‬‬\n\f281\n\f282\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":277,"source_page_end":282,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c8060bbebed4bb02a1a6bf3fe60177f179317a09bd02209a3a6bd1699a9064a9","normalized_text_hash":"7975ec547b903db9b0667ac0892616c9d9dc0675225ca39b1249b079cd7ac2f7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p277-34183270"},{"id":"f546ef11-7d4d-520e-b56d-5eb9e47cd5ad","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقوق والدين -اعتداء على الغير -كشف طبي على املدعى عليه للتأكد من أهليته -صدور تقرير طبي بعدم أهلية املدعى عليه -رد دعوى املدعى العام لعدم أهلية املدعى عليه -حكم بإيداع املدعى عليه يف مصحة نفسية وال يخرج إال بتقرير طبي يثبت زوال خطورته على اآلخرين.","document_number":"34212286","case_number":"3472907","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/13","year":"1434","subject":"عقوق والدين -اعتداء على الغير -كشف طبي على املدعى عليه للتأكد من أهليته -صدور تقرير طبي بعدم أهلية املدعى عليه -رد دعوى املدعى العام لعدم أهلية املدعى عليه -حكم بإيداع املدعى عليه يف مصحة نفسية وال يخرج إال بتقرير طبي يثبت زوال خطورته على اآلخرين.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                   ‫رقم الصك ‪ 34212286 :‬تاريخه‪:‬‬\n             ‫‪1434/5/13‬هـ رقم الدعوى‪3472907:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34231533‬تاريخه‪1434/6/5 :‬هـ‬\n\n\n      ‫عقــوق والديــن ‪ -‬اعتــداء علــى الغيــر ‪ -‬كشــف طبــي علــى املدعــى عليــه‬\n      ‫للتأكــد مــن أهليتــه ‪ -‬صــدور تقريــر طبــي بعــدم أهليــة املدعــى عليــه‬\n      ‫‪ -‬رد دعــوى املدعــى العــام لعــدم أهليــة املدعــى عليــه ‪ -‬حكــم بإيــداع‬\n      ‫املدعــى عليــه يف مصحــة نفســية وال يخــرج إال بتقريــر طبــي يثبــت زوال‬\n                                                        ‫خطورتــه علــى اآلخريــن‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة يف تســبيب‬\n                                                                           ‫حكمه ‪.‬‬\n\n\n\n      ‫انتهــى التحقيــق مــع املدعــى عليــه إلــى اتهامــه بعقــوق والدتــه وضربهــا‬\n      ‫وضــرب شــقيقته‪ ،‬وذلــك بعدمــا تلقــت اجلهــات املختصــة بالغــا مــن‬\n      ‫والــد املدعــى عليــه مفــاده أن ابنــه قــام بضــرب والدتــه وشــقيقته وإيــذاء‬\n      ‫جيرانــه‪ -‬بالبحــث عــن ســوابقه اتضــح وجــود خمــس ســوابق مســجلة‬\n      ‫عليــه األولــى ســرقة حيوانــات والثانيــة تخلــف عــن الصــاة والثالثــة‬\n      ‫ترويــج وحيــازة املخــدرات والرابعــة طعــن شــخص واخلامســة اشــتباه يف‬\n      ‫ترويــج مخــدرات‪ ،‬طلــب املدعــي العــام احلكــم عليــه بعقوبــة تعزيريــة‪.‬‬\n      ‫عنــد اســتجواب املدعــى عليــه ظهــر عــدم اســتقراره وعــدم فهمــه للدعوى‬\n\n‫‪283‬‬\n\f‫وشــروده الذهنــي ومحاولتــه اخلــروج ممــا يوحــي أنــه يعانــي مــن مــرض‬\n‫عقلــي‪ ،‬مت عــرض املدعــى عليــه علــى اللجنــة الطبيــة النفســية اجلنائيــة‬\n‫واتضــح أنــه يعانــي مــن الفصــام العقلــي ‪،‬كمــا جــرى االطــاع علــى‬\n‫التقريــر الطبــي املرفــق باملعاملــة املتضمــن أن املدعــى عليــه يعانــي مــن‬\n‫الفصــام‪ ،‬ظهــر أثنــاء اجللســة أن املدعــى عليــه غيــر مــدرك ملــا يــدور حوله‬\n‫وال يســتجيب لالســتجواب ويرفــض اجللــوس ويحــاول التفلــت مــن اخلفــراء‬\n‫املرافقــن واالعتــداء عليهــم ملرضــه النفســي وعــدم إدراكــه‪ ،‬نظــرا إلــى‬\n‫مــا جــاء يف التقاريــر الطبيــة املذكــورة‪ ،‬ونظــرا إلــى أنــه ظهــر مــن خــال‬\n‫حضــور املدعــى عليــه جلســات احملاكمــة أنــه ال يحســن التصــرف وال‬\n‫ميكــن التخاطــب معــه وال يــدرك مــا حولــه ممــا مينــع معاقبتــه ألنــه يظهــر‬\n‫أنــه مريــض مبــرض عقلــي ويحتــاج إلــى العــاج ال العقــاب لــذا مت احلكــم‬\n‫بــرد دعــوى املدعــي العــام ضــد املدعــى عليــه لعــدم وجاهــة معاقبتــه ومت‬\n‫األمــر بإحالتــه إلــى املصحــة النفســية املختصــة لعالجــه علــى أال يطلــق‬\n‫ســراحه حتــى يثبــت بتقريــر اللجنــة الطبيــة املختصــة عــدم خطورتــه‬\n‫علــى حيــاة اآلخريــن ‪ ،‬بعــرض احلكــم علــى املدعــي العــام قــرر القناعــة‬\n‫باحلكــم ولكــون املدعــى عليــه لــم يفهــم احلكــم بعــد عرضــه عليــه وال‬\n‫يســتطاع فهــم قناعتــه مــن عدمهــا علــى احلكــم فلذلــك وإبــراء للذمــة مت‬\n   ‫رفــع احلكــم حملكمــة االســتئناف‪ ،‬وبعــد رفعــه متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 3472907‬وتاريــخ ‪ 1434/02/13‬ه ـ املقيــدة‬\n\n                                                                                     ‫‪284‬‬\n\f      ‫باحملكمــة برقــم ‪ 34363827‬وتاريــخ ‪ 1434/02/12‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/02/19‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر‬\n      ‫املدعــي العــام ‪...‬وادعــى علــى احلاضــر معــه ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة الوطنيــة رقــم (‪ )...‬قائــا يف دعــواه (بصفتــي مدعيـ ًا عام ًا يف دائرة‬\n      ‫التحقيــق واالدعــاء العــام مبحافظــة عنيــزة أدعــي علــى ‪ ،...:‬البالــغ مــن‬\n      ‫العمــر (‪ )33‬عام ـاً‪ ,‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪)...‬‬\n      ‫أعــزب‪ ,‬متســبب‪ ,‬يقيــم مبحافظــة عنيــزة‪ ,‬أوقــف بتاريــخ ‪1434/1/24‬ه ـ‬\n      ‫وأحيــل لســجن محافظــة عنيــزة مبوجــب أمــر متديــد التوقيــف للمــرة‬\n      ‫الثانيــة رقــم ( ه ـ ص‪ )849/5/5‬وتاريخ‪1434/2/9‬ه ـ اســتناد ًا للقــرار‬\n      ‫الــوزاري رقــم (‪ )1900‬يف ‪1428/7/9‬ه ـ حيــث إنــه بتاريــخ ‪1434/1/25‬ه ـ‬\n      ‫تلقــت دوريــات األمــن مبحافظــة عنيــزة بالغ ـ ًا مــن والــد املدعــى عليــه‬\n      ‫‪... /‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )...‬يفيــد فيــه بــأن‬\n      ‫ابنــه املدعــى عليــه قــام بضــرب والدتــه وشــقيقته وإيــذاء جيرانــه فتــم‬\n      ‫القبــض عليــه وبضبــط إفــادة والــده أفــاد بــأن ابنــه املدعــى عليــه قــد‬\n      ‫قــام بضــرب والدتــه وشــقيقته وأن جيرانــه يشــتكون منــه كثيــر ًا‬\n      ‫وبضبــط إفــادة والدتــه أفــادت بــأن ابنهــا املدعــى عليــه قــد قــام بضربهــا‬\n      ‫عــدة مــرات وكان يقــوم بخنقهــا ويقــوم بضــرب أشــقائه كثيــراً‪.‬‬\n      ‫وباســتجوابه امتنــع عــن إكمــال االســتجواب وانتهــى التحقيــق معــه‬\n      ‫الــى اتهامــه بعقــوق والدتــه وضربهــا وشــقيقته‪ .‬وذلــك ملــا ورد مبحضــر‬\n      ‫إفــادة والديــه املنــوه عنهــا املدونــة علــى الصفحــة رقــم(‪ )5,4‬مــن دفتــر‬\n      ‫التحقيــق لفــة رقــم (‪ )10‬وباالطــاع علــى نتيجــة بحــث ســوابقه اتضــح‬\n      ‫وجــود خمــس ســوابق مســجلة عليــه األولــى ســرقة حيوانــات والثانيــة‬\n      ‫تخلــف عــن الصــاة والثالثــة ترويــج وحيــازة املخــدرات والرابعــة طعــن‬\n\n\n‫‪285‬‬\n\f‫شــخص واخلامســة اشــتباه يف ترويــج مخــدرات وحيــث إن مــا أقــدم عليــه‬\n‫املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا‬\n‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره) هكــذا‬\n‫ادعــى املدعــي العــام وعنــد محاولــة اســتجواب املدعــى عليــه ظهــر عــدم‬\n‫اســتقراره وعــدم فهمــه للدعــوى وشــروده الذهنــي ومحاولتــه اخلــروج‬\n‫ممــا يوحــي بأنــه يعانــي مــن مــرض عقلــي ولذلــك فقــد أجلــت اســتجوابه‬\n‫وأمــرت بعرضــه علــى اللجنــة الطبيــة املختصــة باألمــراض العقليــة لبيــان‬\n‫أهليتــه العقليــة ويف جلســة أخــرى ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه ‪ ...‬وقــد وردنــا خطــاب ســجن عنيــزة رقــم‬\n‫‪ 2/ 26/ 1874/9‬يف ‪1434/4/2‬ه ـ املتضمــن أنــه مت بعــث الســجني إلــى‬\n‫املصحــة النفســية بالطائــف وبنــاء عليــه فقــد أجلــت اجللســة ويف جلســة‬\n‫أخــرى حضــر املدعــي العــام وقــد حضــر الســجني املدعــى عليــه ‪...‬برفقــة‬\n‫عســكري الســجن مبوجــب خطــاب مديــر ســجن عنيــزة رقــم ‪ 130‬يف‬\n‫‪1434/5/12‬ه ـ وقــد أرفــق بهــذا اخلطــاب صــورة مــن تقريــر مستشــفى‬\n‫الصحــة النفســية بالطائــف املتضمــن أنــه مت عــرض الســجني ســطام‬\n‫حمــد محمــد احلربــي علــى اللجنــة الطبيــة النفســية اجلنائيــة وتضمــن‬\n‫رأي اللجنــة الطبيــة مت مناظــرة املذكــور مــن قبــل اللجنــة وشــخصت‬\n‫حالتــه مبدئيــا \"فصــام عقلــي\" وقــد مت طلــب عمــل محضــر للمخــدرات‬\n‫واختبــار ذكاء للمذكــور ومت إعطــاؤه العــاج الــازم ولكتابــة التقرير‬\n‫النفســي اجلنائــي يرجــى إعــادة عرضــه علــى اللجنــة برفقــة أحــد مــن ذويــه‬\n‫مــع موافاتنــا بأيــة تقاريــر طبيــة ســابقة صــادرة بحقــه وبنتيجــة فحــص‬\n‫املخــدرات وقــت القبــض عليــه‪ .‬انتهــى أعضــاء اللجنــة عضــو د‪.../‬أمــن‬\n‫عضــو د‪.../‬انتهــى كمــا وجــدت يف املعاملــة التقريــر الطبــي الصــادر‬\n\n\n                                                                                    ‫‪286‬‬\n\f      ‫مــن مستشــفى الصحــة النفســية يف بريــدة برقــم ‪/340226‬ت ‪ 45/32/‬يف‬\n      ‫‪1434/2/10‬ه ـ املتضمــن أن املدعــى عليــه له ملــف لديهم منذ عام ‪1422‬هـ‬\n      ‫حيــث شــخصت حالتــه فصــام انتهــى وقــد ظهــر مــن حالــة املدعــى عليــه‬\n      ‫النفســية أثنــاء هــذه اجللســة أنــه غيــر مــدرك ملــا يــدور حولــه وال يســتجيب‬\n      ‫لالســتجواب ويرفــض اجللــوس ويحــاول التفلــت مــن العســكر املرافقــن‬\n      ‫واالعتــداء عليهــم ملرضــه النفســي وعــدم إدراكــه هــذا مــا ظهــر لــي أثناء‬\n      ‫اجللســة فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام املتضمنــة اتهــام‬\n      ‫املدعــى عليــه بعقــوق والدتــه وضربهــا وشــقيقته ونظــرا إلــى مــا جــاء‬\n      ‫يف التقاريــر الطبيــة املذكــورة املتضمــن إصابــة املدعــى عليــه مبــرض‬\n      ‫الفصــام العقلــي ونظــرا إلــى أنــه ظهــر مــن خــال حضــور املدعــى عليــه‬\n      ‫جلســات احملاكمــة أنــه ال يحســن التصــرف وال ميكــن التخاطــب معــه‬\n      ‫وال يــدرك مــا حولــه ممــا مينــع معاقبتــه ألنــه يظهــر أنــه مريــض مبــرض‬\n      ‫عقلــي ويحتــاج إلــى العــاج ال العقــاب وملــا تقــدم كلــه فقــد رددت دعــوى‬\n      ‫املدعــي العــام ضــد املدعــى عليــه لعــدم وجاهــة معاقبتــه وأمــرت بإحالــة‬\n      ‫املدعــى عليــه إلــى املصحــة النفســية املختصــة لعالجــه علــى أال يطلــق‬\n      ‫ســراحه حتــى يثبــت بتقريــر اللجنــة الطبيــة املختصــة عــدم خطورتــه‬\n      ‫علــى حيــاة اآلخريــن وبجميــع مــا تقــدم حكمــت وبعــرض احلكــم علــى‬\n      ‫الطرفــن قــرر املدعــي العــام القناعــة باحلكــم ولكــون املدعــى عليــه لــم‬\n      ‫يفهــم احلكــم بعــد عرضــه عليــه ولــم نســتطع فهــم قناعتــه مــن عدمهــا‬\n      ‫علــى احلكــم فلذلــك وإبــراء للذمــة فقــد قــررت رفــع احلكــم حملكمــة‬\n      ‫االســتئناف لتدقيقــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم حــرر يف ‪ 1434/05/13‬ه ـ احلمــد هلل وحــده وبعــد‬\n      ‫فلــدي أنــا ‪ ......‬رئيــس احملكمــة القائــم بعمــل فضيلــة الشــيخ فهــد بــن‬\n\n\n‫‪287‬‬\n\f‫‪...‬وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 3472907‬وتاريــخ ‪ 1434/02/13‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34363827‬وتاريــخ ‪ 1434/02/12‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/06/24‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بالقصيــم برقــم ‪341224775‬يف ‪1434/6/18‬ه ـ‬\n‫وبرفقهــا قــرار محكمــة االســتئناف بالقصيــم رقــم ‪ 34231533‬يف‬\n‫‪1434/6/5‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة قررنــا باألكثريــة املصادقــة علــى احلكــم واهلل‬\n‫املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن و‬\n                                      ‫للمعلوميــة حــرر يف ‪1434/6/24‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪288‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":283,"source_page_end":288,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9c93f909320f3de1f85989da3548b91294e270a214d6e06da7e5c14181a018f6","normalized_text_hash":"326531596d08827ec157fd02b257f339cb5da9c97a9f61e7818d6715ff60ca1d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p283-34212286"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

